    nm_demo_title: "Bí pípààrọ̀ ṣe ń ṣiṣẹ́",
    faq_a_new_me_challenge_journal: "Nígbà tí ìpèníjà kan bá parí – ńlá, kékeré tàbí ìpèníjà ọ̀sẹ̀ – bọ́tìnnì 📝 Báwo ló ṣe lọ? máa ń wà nínú ayẹyẹ náà. Ó ń ṣí ojú-ewé kan nínú ìwé ìrántí ìpèníjà: bí ó ṣe rí lára (ojú márùn-ún), ohun tó ṣèrànwọ́, ohun tó le àti ohun tí màá mú lọ láti ibí – kò sí èyí tí ó pọn dandan, ó sì lè dúró di ìgbà míì. Ìwé ìrántí náà jẹ́ dáyámọ́ǹdì kan nínú àpò idán: gbogbo ìpèníjà tó ti parí pẹ̀lú ọjọ́ rẹ̀ àti ohun tí a kọ, èyí tó jẹ́ tuntun jù ló kọ́kọ́ hàn – tẹ ọ̀kan láti kà á, ṣàtúnṣe rẹ̀ tàbí pín in (ohun tó wà lójú-ewé nìkan ni a ń pín). Ìpèníjà tó ti parí tún máa ń gba àmì-ẹ̀yẹ kan nínú àṣeyọrí, lábẹ́ “Àwọn ìpèníjà tí mo parí”. Ìwé ìrántí ìpèníjà yàtọ̀ sí ìwé-ìrántí déédéé.",
