    nm_chj_write: "Kọ bí ó ṣe lọ",
    nm_swap_time: "Àkókò",
    faq_a_ai_reminder_in_text: "Bẹ́ẹ̀ni – kọ ọ́ papọ̀ mọ́ iṣẹ́ náà, fún àpẹẹrẹ “ọ̀la ní 17:00 lọ gba ẹrù náà, pẹ̀lú ìránnilétí wákàtí kan ṣáájú”. A máa ń fi ìránnilétí náà pamọ́ sórí iṣẹ́ náà fúnra rẹ̀: wákàtí kan ṣáájú, ààbọ̀ wákàtí, ọjọ́ kan ṣáájú àti bẹ́ẹ̀ bẹ́ẹ̀ lọ, àti “rán mi létí” láìsí àkókò túmọ̀ sí ìṣẹ́jú 10 ṣáájú. Ìránnilétí tí a kọ sínú ọ̀rọ̀ ni ó ṣáájú àyè ìránnilétí tí ó wà nínú fèrèsé kan náà.",
    faq_q_ai_reminder_in_text: "Ṣé mo lè béèrè ìránnilétí lọ́wọ́ olùrànlọ́wọ́ AI nínú ìbéèrè kan náà?",
    myday_meals_all_done: "A ti sàmì sí gbogbo oúnjẹ òní 🍽️",
    nm_tour_week_text: "Ìpèníjà kékeré fún ọ̀sẹ̀. ✓ lójoojúmọ́ – kọ́kọ́rọ́ ní òpin.",
    books_home_chip: "{title} · ojú ìwé {page}",
    books_home_of: "nínú {total}",
    books_home_off_toast: "Ìwé náà kúrò lórí ojú-ìwé ilé",
    books_home_on_toast: "Ìwé náà wà lórí ojú-ìwé ilé 📖",
    books_home_pin: "Lórí ojú-ìwé ilé",
    books_home_q: "Ojú ìwé wo ni mo wà?",
    books_home_save: "Fi pamọ́",
    faq_a_books_home_chip: "Bẹ́ẹ̀ ni. Ní Igun Kíkà, lórí káàdì ìwé tí o ń kà lọ́wọ́, fọwọ́ kan 📌 Lórí ojú-ìwé ilé. Bọ́tìnnì kékeré kan pẹ̀lú ìwé àti ojú ìwé yóò hàn lábẹ́ ìkíni lórí ojú-ìwé ilé – fọwọ́ kàn án, tẹ nọ́mbà ojú ìwé tuntun, kí o sì fi pamọ́, a ó sì tọpa ìlọsíwájú náà (ní Igun Kíkà náà). Fífọwọ́ kan 📌 lẹ́ẹ̀kan sí i yóò mú un kúrò. Ìwé púpọ̀ lè wà níbẹ̀ papọ̀ – bọ́tìnnì kan fún ọ̀kọ̀ọ̀kan – ó sì jẹ́ bákan náà lórí gbogbo ẹ̀rọ.",
    faq_a_new_me_week_challenge: "Ìpèníjà kékeré fún ọ̀sẹ̀ kan, tí o yàn fúnra rẹ. Nínú ọ̀dẹ̀dẹ̀, káàdì ńlá kan wà: “Kí ni o fẹ́ ṣiṣẹ́ lé lórí ní ọ̀sẹ̀ yìí?” – fọwọ́ kàn án, yan ẹ̀ka kan (pẹ̀lú ara mi, pẹ̀lú àwọn ẹlòmíràn, kọ́ àti dàgbà, ìbàlẹ̀ ọkàn, àwọn ìgbésẹ̀ kékeré onígboyà, ilé àti ìlànà) àti ìpèníjà kan, kí o sì yan ìgbà tí yóò bẹ̀rẹ̀. Àwọn ìpèníjà kan náà wà lórí ojú-ìwé àwọn ìpèníjà, lábẹ́ 🌱 Ìdàgbàsókè ara ẹni. Lójoojúmọ́ fi ✓ sórí káàdì náà (ọjọ́ ọ̀fẹ́ kan lọ́sẹ̀), ọ̀sẹ̀ kọ̀ọ̀kan tí ó bá parí sì ń mú kọ́kọ́rọ́ tuntun wá fún ayé àṣírí náà. “Ka ojú ìwé 2 lójoojúmọ́” máa ń fi àmì sí fúnra rẹ̀ láti inú àwọn ojú ìwé tí a kọ sílẹ̀ ní Igun Kíkà. Nígbà tí ọ̀sẹ̀ bá parí, 📌 Pa á mọ́ gẹ́gẹ́ bí iṣẹ́ ojoojúmọ́ yóò fi kún Ìlànà Mi ní àkókò tí o yàn, pẹ̀lú ✓ lójoojúmọ́. Ìpèníjà ọ̀sẹ̀ kan ṣoṣo ló máa ń lọ ní ìgbà kan; àwọn ìpèníjà ńlá àti kékeré ń tẹ̀ síwájú lẹ́gbẹ̀ẹ́ rẹ̀.",
    faq_a_room_genie: "Ní ìloro tí ó kọjú sí òkun, fífọwọ́ kan àtùpà Aladdin ń mú ẹ̀mí igbó jáde – ìjíròrò sì bẹ̀rẹ̀: kí ni ìfẹ́ ọkàn rẹ (kí ni o fẹ́ yí padà nínú ayé rẹ), báwo ni yóò ṣe rí lára nígbà tí ó bá ṣẹ, kí ni ó le ní ọ̀nà, àti bí a ṣe lè yí ipò tí ó wà báyìí padà sí rere. Lẹ́yìn náà, nǹkan bí ìgbà tó máa gbà, ìgbésẹ̀ àkọ́kọ́ kékeré àti méjì sí i, àti “bí… nígbà náà…” fún ìgbà tí ó bá le. Ní ìparí, gbogbo ìfẹ́ ọkàn náà yóò hàn ní ìgbésẹ̀ lẹ́yìn ìgbésẹ̀, a sì lè sọ ọ́ di góńgó nínú Àwọn Góńgó Mi (àwọn ìgbésẹ̀ yóò di ibùdó lójú ọ̀nà, pẹ̀lú déètì ní ìbámu pẹ̀lú àkókò tí a yàn; a lè yí gbogbo rẹ̀ padà níbẹ̀) tàbí kí a fi pamọ́ sínú ìwé-ìrántí – lẹ́yìn náà ẹ̀mí náà yóò dágbére. A kì í fi nǹkan pamọ́ àyàfi tí a bá yan ọ̀kan nínú wọn. Láti ìbẹ̀wò kejì lọ, ẹ̀mí náà yóò kọ́kọ́ béèrè bóyá o fẹ́ yí nǹkan mìíràn padà nínú ayé rẹ: bẹ́ẹ̀ ni – ìjíròrò kan náà; kì í ṣe báyìí – ìránnilétí láti dé àwọn góńgó tí a ti gbé kalẹ̀. Ẹ̀mí náà máa ń jáde lẹ́ẹ̀kan lójúmọ́: lẹ́yìn tí a bá fi ìfẹ́ ọkàn kan pamọ́ (tàbí lẹ́yìn “Kì í ṣe báyìí”), yóò sinmi títí di ọ̀la. Àwọn ìbéèrè náà tẹ̀lé ọ̀nà tí a mọ̀ dáadáa láti sọ ìfẹ́ ọkàn di ètò: ìfẹ́ ọkàn, àbájáde, ìdènà àti ètò.",
