    room_drawer_aria: "Àpótí kékeré",
    nm_me_choose: "Yàn",
    nm_me_on_screen: "Lórí ojú-ìwé",
    faq_a_new_me_game: "Nínú New Me, àwọn bọ́tìnnì eré máa ń wà níbì kan náà nígbà gbogbo – nínú ọ̀dẹ̀dẹ̀, nínú yàrá àṣírí àti níbi gbogbo nínú igbó; àwòrán àárín nìkan ló ń yí padà. Ní òkè: ọjọ́ nínú ìrìn-àjò, àwọn kọ́kọ́rọ́, ọjọ́ léraléra àti agbára òní (iye tí a ti jẹ nínú ètò), lábẹ́ rẹ̀ sì ni iṣẹ́ tó kàn – oúnjẹ tó kàn ní àkókò rẹ̀ (fífọwọ́kàn án ń ṣí i, pẹ̀lú ✓ Mo ti jẹ ẹ́). Ní ẹ̀gbẹ́: gbogbo ọjọ́, àwọn ìpèníjà àti ìrìn-àjò mi, lẹ́gbẹ̀ẹ́ wọn sì ni ìpèníjà ọ̀sẹ̀ – ọjọ́ 7 rẹ̀ àti ✓ fún òní. Ní ìsàlẹ̀: àpò idán (gbogbo New Me – máàpù ayé, ìrìn-àjò mi, àtòjọ ọjà, àṣeyọrí, ìwé ìrántí ìpèníjà, ìwọ̀n ara, àwòrán, kàlẹ́ńdà oṣù, tábìlì ojoojúmọ́, ìránnilétí, PDF àkójọ oúnjẹ àti ètò; ó ń ṣí gẹ́gẹ́ bí ojú-ìwé tirẹ̀). Máàpù ayé, ohun àkọ́kọ́ nínú àpò, ń fi gbogbo ibi tó wà nínú igbó hàn – tẹ ibì kan láti lọ síbẹ̀; ibi tí a tì ń fi iye kọ́kọ́rọ́ tí ó nílò hàn. Sky ni ẹ̀dá-ìtàn rẹ lórí ọ̀nà inú igbó: ó bẹ̀rẹ̀ bí Sky 1, lẹ́yìn ìpèníjà díẹ̀ (kọ́kọ́rọ́ 4) ó dàgbà di Sky 2, nígbà tí òpin bá sì súnmọ́ (kọ́kọ́rọ́ 9) ó di Sky 3 – pẹ̀lú ìyípadà ńlá tí o lè wò. Tẹ Sky láti rí gbogbo ìpele – o lè tún yan ìpele èyíkéyìí tí o ti dé, nítorí náà èyí tó ṣáájú lè padà wá. Sky ń léfòó – a lè fà á pẹ̀lú ìka tàbí eku, ẹnu-ọ̀nà tó bá fọwọ́ kàn yóò sì ṣí (èyí tí a tì máa ń fi iye kọ́kọ́rọ́ tó kù hàn). Sky tún ń bá ọ wá sí gbogbo yàrá àti gbogbo ibi, ó sì ń léfòó níbi tí o bá fi sílẹ̀: fà á lọ síbikíbi, kí o sì fa òrùka tó ń tàn lábẹ́ rẹ̀ láti yí i po pátápátá; ó máa ń kọjú sí ọ̀nà tí ó ń lọ (lórí kọ̀ǹpútà: àwọn ọfà ń gbé e, Q àti E ń yí i). Nínú ọ̀dẹ̀dẹ̀, 🏠 kékeré tí ó wà lábẹ́ ìlà òkè náà ń padà sí ojú-ìwé ilé; ní yàrá kọ̀ọ̀kan àti ibi kọ̀ọ̀kan, bọ́tìnnì tó wà ní igun kan náà ń padà sí ọ̀dẹ̀dẹ̀.",
    faq_q_new_me_game: "Báwo ni àwọn bọ́tìnnì eré, máàpù ayé àti Sky ṣe ń ṣiṣẹ́?",
