    faq_a_new_me_menu_build: "Lákọ̀ọ́kọ́, ìwé-ìbéèrè máa béèrè àwọn oúnjẹ tí o ń jẹ àti ìgbà wo (Oúnjẹ 2 + ìpanu, Oúnjẹ 2 + oúnjẹ alẹ́ fẹ́ẹ́rẹ́, tàbí méjèèjì), àti bóyá nǹkan kan wà ní ìrọ̀lẹ́ – láti jẹ tàbí láti mu, kí ni, àti ní agogo mélòó. Pẹ̀lú “Oúnjẹ 2 + ìpanu”, àwọn oúnjẹ náà ni oúnjẹ ọ̀sán (11:30) àti oúnjẹ alẹ́ (19:00), ìpanu sì wà ní 16:00. Lẹ́yìn náà gbogbo àṣàyàn fún àwọn oúnjẹ yẹn máa hàn. Yan tó àyànfẹ́ 2 fún oúnjẹ kọ̀ọ̀kan – àkójọ oúnjẹ máa kọ “èyí tàbí ìyẹn”. Nínú àwọn àṣàyàn kan (pita àti ìpara, corn flakes àti wàrà, nǹkan fífúyẹ́) o máa yan tó nǹkan 3 tí o fẹ́ràn, ọ̀kọ̀ọ̀kan ní ìwọ̀n tirẹ̀, àkójọ oúnjẹ sì máa kọ “èyí tàbí ìyẹn tàbí ìyẹn”; kálórì máa tẹ̀lé ohun tí o yàn. Kọfí àti ohun mímu ń ṣiṣẹ́ bákan náà. Gbogbo àṣàyàn ni a ń dọ́gba, nítorí náà àpapọ̀ ọjọ́ máa jẹ́ 1,300 tàbí 1,500 gẹ́lẹ́. Láti yí i padà nígbàkígbà: ⚙️ Ètò → 🍽️ Ṣe àkójọ oúnjẹ rẹ, tàbí “Yan tó 3 tí o fẹ́ràn” lórí káàdì oúnjẹ náà.",
    faq_q_new_me_menu_build: "Báwo ni a ṣe ń ṣe àkójọ oúnjẹ New Me?",
