    faq_a_myday_water_toggle: "Bẹ́ẹ̀ni. Ife omi nínú 'Ọjọ́ Mi' (pẹ̀lú + fún ife kan sí i) máa ń hàn látìbẹ̀rẹ̀. Láti fi pamọ́, pa \"Ṣàfihàn omi nínú 'Ọjọ́ Mi'\" nínú Ètò > Ìṣàkóso ti ara ẹni àti Kàlẹ́ndà. Kò sí ohun tí a pa rẹ́ – Àbójútó Omi ń ṣiṣẹ́ lọ, tí a bá sì tún tàn án, ife náà á padà.",
    faq_q_myday_water_toggle: "Ṣé a lè fi omi pamọ́ nínú 'Ọjọ́ Mi'?",
    myday_water_toggle_label: "Ṣàfihàn omi nínú 'Ọjọ́ Mi'",
    faq_a_routine_newme_sync: "Tí o bá ní New Me, ⚙️ Ìlànà Mi ní ìyípadà 'Ṣe ìbámu pẹ̀lú New Me'. Tí ó bá wà ní títàn (àtilẹ̀wá), oúnjẹ New Me ti òní ń hàn nínú Ọjọ́ Mi àti nínú Ìlànà Mi – ní ipò àwọn oúnjẹ ìlànà tí a fi pamọ́. Tí ó bá wà ní pípa, oúnjẹ New Me máa kúrò nínú méjèèjì, ìlànà náà sì máa padà sí bí ó ṣe wà gẹ́lẹ́. Kò sí ohun tí a pa rẹ́ – títàn án padà máa mú gbogbo rẹ̀ padà, yóò sì béèrè oúnjẹ ìlànà wo ni kí a fi pamọ́.",
    faq_q_routine_newme_sync: "Báwo ni mo ṣe lè tan tàbí pa ìbámu New Me pẹ̀lú Ìlànà Mi àti Ọjọ́ Mi?",
    routine_newme_sync_label: "Ṣe ìbámu pẹ̀lú New Me",
    routine_newme_sync_off_toast: "Ìbámu ti pa – oúnjẹ New Me ti kúrò nínú Ọjọ́ Mi, ìlànà rẹ sì ti padà sí bí ó ṣe wà",
    routine_newme_sync_on_toast: "A ti ṣe ìbámu pẹ̀lú New Me – oúnjẹ rẹ̀ wà nínú Ọjọ́ Mi",
