    theme_name_watercolor_wash: "Àwọ̀ Omi",
    faq_a_food_list_languages: "Àtòjọ oúnjẹ tó wà nínú ohun èlò náà bẹ̀rẹ̀ pẹ̀lú oúnjẹ Ísírẹ́lì àti orúkọ Hébérù wọn. Ní gbogbo èdè mìíràn, oúnjẹ kọ̀ọ̀kan ń hàn pẹ̀lú orúkọ Gẹ̀ẹ́sì rẹ̀, ìwádìí sì ń rí orúkọ Gẹ̀ẹ́sì èyíkéyìí tí ó mọ̀ (fún àpẹẹrẹ 'broth' ń rí Clear soup); oúnjẹ tí ó ní orúkọ Hébérù nìkan kì í hàn níbẹ̀. Ohunkóhun tí kò sí nínú àtòjọ, o lè kọ ọ́ ní ọ̀rọ̀ tìrẹ – ìṣirò AI ń ṣiṣẹ́ ní gbogbo èdè.",
    faq_q_food_list_languages: "Kí nìdí tí àtòjọ oúnjẹ fi ń fi orúkọ Gẹ̀ẹ́sì hàn, tí oúnjẹ sì kéré, ní èdè mi?",
    settings_copyright_line: "© 2026 gbogbo ẹ̀tọ́ wà ní ìpamọ́. eden zabari ló ṣe ohun èlò yìí.",
    workout_ready_replace_btn: "Rọ́pò",
    faq_a_sport_workout_ai: "Nínú \"Àwọn eré-ìmárale mi\" → ⋯ → \"Ètò pẹ̀lú AI\" (nígbà tí tábìlì bá ṣófo, ó tún wà lórí káàdì lẹ́gbẹ̀ẹ́ àwọn ètò tó ti ṣetán). Fi ìfọwọ́kàn díẹ̀ dáhùn – ìgbà mélòó lọ́sẹ̀, ìgbà wo, ibì, ìpele àti àfojúsùn, ọ̀pọ̀ nínú wọn ní \"Òmíràn\" pẹ̀lú – o sì lè fi ìlà kan kún un bí o bá fẹ́, bí orúnkún tó ń dunni tàbí sísáré 5 km kí ẹ̀ẹ̀rùn tó dé. AI ń ṣe ọ̀sẹ̀ kan pátápátá: irú eré-ìmárale, àwọn ọjọ́, àkókò, ìgbà tó gbà, agbára, ìdánrawò àti àwọn ọjọ́ ìsinmi. Kí ohunkóhun tó di fífipamọ́, àwòtẹ́lẹ̀ máa ń hàn: \"Fi sínú tábìlì mi\" (dípò tábìlì náà tàbí láfikún sí i), \"Àbá mìíràn\" (tó ìgbà 3) tàbí \"Yí àwọn ìdáhùn padà\". Ètò náà wà ní ìwọ̀ntúnwọ̀nsì ní àmọ̀ọ́mọ̀ṣe, bí o bá sì mẹ́nu kan ìrora tàbí ìpalára, wàá rí àwọn àṣàyàn jẹ́jẹ́ àti ìmọ̀ràn láti bá ògbóǹtarìgì sọ̀rọ̀. Ó ń lo ìpín AI kan náà pẹ̀lú ètò ojoojúmọ́ àti ìlànà: ìgbà 5 lọ́fẹ̀ẹ́, àti ìgbà 60 lóṣù pẹ̀lú Premium.",
    faq_q_sport_workout_ai: "Báwo ni mo ṣe lè ṣe ètò eré-ìmárale pẹ̀lú AI?",
