    workout_ai_other: "Òmíràn",
    workout_ai_replace: "Dípò tábìlì mi",
    workout_ai_title: "Ètò eré-ìmárale pẹ̀lú AI",
    workout_ai_when_evening: "Ìrọ̀lẹ́",
    workout_ai_when_label: "Ìgbà wo",
    workout_ai_when_morning: "Àárọ̀",
    workout_ai_when_noon: "Ọ̀sán",
    workout_ai_when_ph: "àpẹẹrẹ lẹ́yìn iṣẹ́, tàbí 17:30",
    workout_ai_working: "A ń ṣe ètò náà…",
    faq_a_sport_workout_jar: "Irú eré-ìmárale kọ̀ọ̀kan ní ìràwọ̀ aláwọ̀ tirẹ̀ – sísáré píńkì, rírìn ewé, lúwẹ̀ẹ́ búlúù, bẹ́ẹ̀ bẹ́ẹ̀ lọ. Gbogbo eré-ìmárale tí a kọ sílẹ̀ ní ọ̀sẹ̀ yìí, láti inú tábìlì tàbí lọ́tọ̀, ń ju ìràwọ̀ rẹ̀ sínú ìgò tó wà lókè \"Àwọn eré-ìmárale mi\", ìgò náà sì ń kún títí dé àfojúsùn ọ̀sẹ̀ rẹ (fọwọ́ kàn án láti yí àfojúsùn padà). Nígbà tí a bá dé àfojúsùn, ìgò náà ń tàn. Ìgò kékeré tó wà lẹ́gbẹ̀ẹ́ rẹ̀ ń ka iye ọ̀sẹ̀ tó tẹ̀lé ara wọn tí ó kún.",
    faq_q_sport_workout_jar: "Kí ni àwọn ìràwọ̀ aláwọ̀ àti ìgò nínú \"Àwọn eré-ìmárale mi\"?",
    faq_a_sport_workout_gcal: "Bẹ́ẹ̀ni – nínú ⋯ → Kàlẹ́ńdà Google (lẹ́yìn tí o bá so Kàlẹ́ńdà Google pọ̀ nínú Ètò). Eré-ìmárale kọ̀ọ̀kan tó ní àkókò di ìṣẹ̀lẹ̀ tó ń tún ṣẹlẹ̀ ní ọ̀sẹ̀ kọ̀ọ̀kan ní àwọn ọjọ́ rẹ̀, àwọn àyípadà nínú áàpù sì ń ṣe àtúnṣe rẹ̀. Ìránnilétí ń wá láti inú áàpù nìkan, nítorí náà Google kò ní fi tirẹ̀ kún un, àwọn eré-ìmárale kò sì ní hàn lẹ́ẹ̀mejì nínú áàpù. Fífọwọ́ kàn án lẹ́ẹ̀kan sí i ń yọ àwọn eré-ìmárale nìkan kúrò nínú Kàlẹ́ńdà Google.",
    faq_q_sport_workout_gcal: "Ṣé àwọn eré-ìmárale mi lè hàn nínú Kàlẹ́ńdà Google?",
    workout_gcal_btn: "Kàlẹ́ńdà Google",
    workout_gcal_error: "A kò lè ṣe àtúnṣe Kàlẹ́ńdà Google – a ó tún gbìyànjú nígbà àyípadà tó kàn",
    workout_gcal_not_connected: "Kọ́kọ́ so Kàlẹ́ńdà Google pọ̀ nínú Ètò",
    workout_gcal_off_toast: "A ti yọ àwọn eré-ìmárale kúrò nínú Kàlẹ́ńdà Google",
    workout_gcal_on_toast: "Àwọn eré-ìmárale rẹ ti wà nínú Kàlẹ́ńdà Google",
    faq_a_sport_workout_reminder: "Bẹ́ẹ̀ni – nínú eré-ìmárale kan, Ìránnilétí: ìṣẹ́jú 10, ìṣẹ́jú 30 tàbí wákàtí kan ṣáájú, tàbí àkókò tìrẹ (eré-ìmárale náà nílò àkókò). Ó ń dún bí àwọn ìránnilétí míì, lẹ́ẹ̀kan àti ní ibì kan ṣoṣo: nínú áàpù bí ó bá ṣí sílẹ̀, bí bẹ́ẹ̀ kọ́ lórí fóònù rẹ. \"Ó ti parí\" ń kọ eré-ìmárale sínú ìtàn, \"Kò tíì\" sì ń rán ọ létí lẹ́ẹ̀kan sí i lẹ́yìn ìṣẹ́jú 5.",
    faq_q_sport_workout_reminder: "Ṣé mo lè gba ìránnilétí ṣáájú eré-ìmárale?",
    workout_reminder_30min: "Ìṣẹ́jú 30 kí ó tó dé",
    workout_reminder_label: "Ìránnilétí",
    workout_reminder_need_time: "Fi àkókò kún un kí o lè gba ìránnilétí",
    faq_a_sport_workout_share: "Nínú ⋯ → Pín in, ọ̀sẹ̀ náà di àwòrán bí gíláàsì ní àwọ̀ àkọ́lé rẹ, pẹ̀lú ìjápọ̀ jẹ́jẹ́ sí áàpù (lórí fóònù ó lọ tààrà sí àṣàyàn pínpín, lórí kọ̀mpútà a fi àwòrán pamọ́). ⋯ → PDF láti tẹ̀ ń ṣí ojú-ìwé tó mọ́ ti gbogbo ọ̀sẹ̀, pẹ̀lú àpótí láti sàmì sí lẹ́gbẹ̀ẹ́ eré-ìmárale àti ìdánrawò kọ̀ọ̀kan – yan \"Fi pamọ́ gẹ́gẹ́ bí PDF\" tàbí tẹ̀ ẹ́. Ètò náà tún hàn nínú ìjábọ̀ dátà nínú Ètò, lábẹ́ Eré-ìdárayá.",
    faq_q_sport_workout_share: "Báwo ni mo ṣe ń pín tàbí tẹ ọ̀sẹ̀ eré-ìmárale mi?",
    share_image_saved: "A ti fi àwòrán pamọ́ – o lè so ó mọ́ ọn",
    share_save_image: "Fi àwòrán pamọ́",
    workout_pdf_btn: "PDF láti tẹ̀",
    workout_share_btn: "Pín in",
    faq_a_sport_workout_board: "Nínú ⋯ → Pátákó ọ̀sẹ̀ ọjọ́ kọ̀ọ̀kan jẹ́ ọ̀wọ́n kan: fa eré-ìmárale lọ sí ọjọ́ míì (lórí fóònù, tẹ̀ ẹ́ mọ́lẹ̀ pẹ́ ná). Nínú eré-ìmárale kan, \"Nínú Ìlànà Mi pẹ̀lú\" ń fi sínú ìlànà rẹ ní àkókò àti àwọn ọjọ́ rẹ̀, àwọn àyípadà sì ń bá ara wọn mu ní ọ̀nà méjèèjì; láti inú ohun kan nínú Ìlànà Mi, \"Fi kún eré-ìmárale mi\" ń ṣe òdìkejì rẹ̀. ✓ ní ibì kankan ń kà ní méjèèjì, nínú Ọjọ́ Mi ó sì ń hàn lẹ́ẹ̀kan ṣoṣo – nínú àmì tó wà lẹ́gbẹ̀ẹ́ omi.",
    faq_q_sport_workout_board: "Báwo ni mo ṣe ń gbé eré-ìmárale lọ sí ọjọ́ míì, tí mo sì ń so ó mọ́ Ìlànà Mi?",
