    workout_view_board: "Pátákó ọ̀sẹ̀",
    workout_view_timeline: "Ìlà àkókò",
    faq_a_sport_workout_plan: "Nínú Àkọsílẹ̀ Eré-ìmárale, lábẹ́ \"Àwọn eré-ìmárale mi\": + Eré-ìmárale – irú, àwọn ọjọ́, àkókò, ìgbà tó gbà, agbára rẹ̀ àti ibì (àti \"Òmíràn\"). Eré agbára, iṣẹ́-ara àti lúwẹ̀ẹ́ lè ní àkójọ ìdánrawò, \"Ìsinmi\" sì ń sàmì sí ọjọ́ ìsinmi. O tún lè bẹ̀rẹ̀ pẹ̀lú ètò tó ti ṣetán. Eré-ìmárale òní hàn ní ńlá, gbogbo ọ̀sẹ̀ sì wà nísàlẹ̀ rẹ̀; ✓ ń kọ ọ́ sínú ìtàn eré-ìmárale pẹ̀lú agbára rẹ̀. Nínú ⋯ ni a ti ń ṣètò àfojúsùn ọ̀sẹ̀ (eré-ìmárale tàbí ìṣẹ́jú) – gbogbo eré-ìmárale tí a ṣe ń ju ìràwọ̀ rẹ̀ sínú ìgò.",
    faq_a_sport_workout_today: "Nínú Ọjọ́ Mi, lẹ́gbẹ̀ẹ́ omi, àmì kékeré kan ń fi eré-ìmárale òní hàn – fífọwọ́ kàn án ń ṣí àlàyé, ✓ àti ▶. ▶ ń bẹ̀rẹ̀ aago tó ń bá a lọ nínú àmì ojú-ìwé àkọ́kọ́, \"Parí\" sì ń kọ eré-ìmárale sílẹ̀ pẹ̀lú àkókò gidi. Bí ìpèníjà \"Ọ̀sẹ̀ méjì ìgbòkègbodò\" nínú New Me bá ń lọ lọ́wọ́, eré-ìmárale tí a kọ sílẹ̀ yóò kà nínú rẹ̀ fúnra rẹ̀.",
