    faq_a_new_me_magic_themes: "Àwọn àwòrán márùn-ún tó ń dán tí ó wà nínú New Me: Igbó Idán, Erùpẹ̀ Ìràwọ̀, Ìwin Òdòdó, Ìmọ́lẹ̀ Idán àti Ìrọ̀lẹ́ Wúrà. Yan ọ̀kan nínú New Me (⚙️ Ètò > Àwọ̀) tàbí ní Ètò > Ìrísí àti Ìfihàn, búrọ́ọ̀ṣì tó ń dán yóò sì kun ojú-ìwé náà pẹ̀lú rẹ̀. Àwòrán idán máa ń fi ìdán sí gbogbo áàpù àti ní gbogbo ìfọwọ́kàn. O lè padà sí àwòrán mìíràn nígbàkígbà.",
