    quotes_look_wall: "Ògiri",
    theme_magic_section_label: "Àwọn àwòrán idán New Me",
    apptour_focus_text: "Gbogbo nǹkan yóò yẹra àyàfi ohun kan ṣoṣo ti ìsinsìnyí – pẹ̀lú ✓ ńlá. Lẹ́yìn náà èyí tó kàn yóò hàn.",
    apptour_m_presets_text: "Àwọn oúnjẹ tí o fipamọ́ níbì kan: ìwádìí, èyí tí o lò láìpẹ́, gẹ́gẹ́ bí àkókò ọjọ́ – ＋ sì ń fi ọ̀kan kún ti òní.",
    apptour_night_text: "🌙 ń mú gbogbo áàpù náà ṣókùnkùn; ☀️ ń mú ọ̀sán padà.",
    apptour_noteline_text: "Kọ ọ́ kí o sì tẹ ➤ – yóò wà nínú àkọsílẹ̀ rẹ. 📝 ní ìbẹ̀rẹ̀ ń yí padà sí 🛒 rírajà tàbí 🍎 oúnjẹ tí a fipamọ́.",
    apptour_search_text: "Àkọsílẹ̀, rírajà, kàlẹ́ńdà, ìlànà oúnjẹ, ìwé àkọsílẹ̀, àfojúsùn, tábìlì àti ìwé – ìwádìí kan ṣoṣo ń rí gbogbo rẹ̀.",
    faq_a_new_me_ai_menu: "Ṣáájú àtòjọ oúnjẹ, ìwé ìbéèrè náà máa ń béèrè àwọn oúnjẹ tí o ń jẹ àti ìgbà wo (oúnjẹ 2 + ìpanu, oúnjẹ 2 + oúnjẹ alẹ́ fẹ́ẹ́rẹ́, tàbí méjèèjì), bóyá o máa ń jẹ nǹkan kékeré ní ìrọ̀lẹ́ àti ní agogo mélòó, ohun tí o kì í jẹ, àti bí o ṣe ń mu kọfí tàbí tíì. Lẹ́yìn náà AI máa ń ṣe àṣàyàn 3 fún oúnjẹ kọ̀ọ̀kan – ọ̀kọ̀ọ̀kan tó ìpín oúnjẹ yẹn nínú ọjọ́, nítorí náà àpapọ̀ ọjọ́ ṣì jẹ́ 1,300 tàbí 1,500 gẹ́lẹ́ – pẹ̀lú èrò ohun mímu, tí a ń fipamọ́ bí ohun mímu rẹ tí kì í yí padà. Yan tó 2 àyànfẹ́ fún oúnjẹ kọ̀ọ̀kan; àwọn àṣàyàn àtòjọ àkọ́kọ́ wà nísàlẹ̀ wọn gan-an, nínú 🔄 Pààrọ̀ wọ́n sì ń wá lẹ́yìn àtòjọ tìrẹ. 🔄 Àwọn àṣàyàn mìíràn ń ṣe àkójọ tuntun (ẹ̀mẹ́ta fún ìwé ìbéèrè kọ̀ọ̀kan). Láti yí ìdáhùn padà tàbí ṣe àtòjọ tuntun nígbàkígbà: ⚙️ Ètò → ✨ Àtòjọ oúnjẹ tìrẹ (AI).",
    faq_q_new_me_ai_menu: "Báwo ni àtòjọ oúnjẹ tìrẹ nínú New Me ṣe ń ṣiṣẹ́?",
