    apptour_skip_part: "Fo apá yìí",
    apptour_start: "Bẹ̀rẹ̀ ìrìn-àjò náà",
    nm_sales_premium: "Ó ní gbogbo Premium nínú",
    nm_unlock_premium: "Gbogbo Premium náà ti ṣí sílẹ̀.",
    settings_sub_status_newme: "Premium wà nínú New Me rẹ.",
    room_back_to_shelf: "Sí pẹpẹ",
    faq_a_new_me_day_total: "Ọjọ́ kọ̀ọ̀kan ń bá ètò náà mu gẹ́lẹ́: àwọn oúnjẹ, nǹkan bí kálórì 150 fún kọfí àti ohun mímu láàárín ọjọ́, àti ohun tí a yàn fún ìrọ̀lẹ́ – nǹkan kékeré láti jẹ tàbí nǹkan láti mu. Fún ìrọ̀lẹ́, yan tó 3 tí o fẹ́ràn (fún àpẹẹrẹ ọ̀gẹ̀dẹ̀ kan, yógọ́ọ̀tì kan tàbí ègé méjì ṣokoléètì dúdú; tàbí tíì ewéko, tíì pẹ̀lú wàrà díẹ̀ tàbí wàrà gbígbóná), a sì yọ kálórì wọn kúrò nínú àwọn oúnjẹ. Gbogbo ìyàn ń dọ́gba fúnra rẹ̀: àṣàyàn tí ó kéré tàbí tí ó tóbi jù, oúnjẹ tí a yọ, oúnjẹ àárọ̀ kékeré àti oúnjẹ kékeré tó ń bá a wá, tàbí ìrọ̀lẹ́ – ìyàtọ̀ náà ni a fi kún àwọn oúnjẹ tàbí a yọ kúrò nínú wọn, ọ̀kọ̀ọ̀kan gẹ́gẹ́ bí ìtóbi rẹ̀, àti lábẹ́ oúnjẹ kọ̀ọ̀kan a kọ iye (+ tàbí −) àti ohun tí a lè fi kún tàbí fi sílẹ̀. Oúnjẹ tí a ti sàmì sí tẹ́lẹ̀ máa wà bí a ṣe kọ ọ́ sílẹ̀. Nínú ìwé-ìbéèrè, oúnjẹ kọ̀ọ̀kan ń fi àtúnṣe rẹ̀ hàn, àpótí kékeré kan sì ń fi oúnjẹ, ohun mímu, ìrọ̀lẹ́ àti àpapọ̀ hàn. Ṣé o fẹ́ nǹkan mìíràn ní ọjọ́ náà? Jẹ́ kí àpapọ̀ kálórì dúró bákan náà tàbí kí ó dín.",
    faq_q_new_me_day_total: "Báwo ni ọjọ́ New Me ṣe ń pé 1,300 / 1,500 gẹ́lẹ́, àti ibo ni a ti ń ka ohun mímu?",
