    nm_less_line: "Kálórì {n} nínú oúnjẹ yìí, kí ọjọ́ lè pé {plan} – fún àpẹẹrẹ {ideas}",
    nm_less_line_late: "Kálórì {n} nínú oúnjẹ yìí, fún nǹkan kékeré ní {time} – fún àpẹẹrẹ {ideas}",
    nm_swap_balanced: "Kálórì {n} ni a pín sí àwọn oúnjẹ, kí ọjọ́ lè pé {plan}",
    books_quotes_chip: "Àwọn ọ̀rọ̀ àyọlò",
    faq_a_book_quotes: "Lórí pẹpẹ nínú yàrá àṣírí (Àwọn ọ̀rọ̀ àyọlò), tàbí nípasẹ̀ àmì kékeré 💬 Àwọn ọ̀rọ̀ àyọlò nínú Igun Kíkà – àkójọ kan náà ni. Tẹ \"+ Ọ̀rọ̀ àyọlò\", kọ gbólóhùn náà kí o sì yan ìwé láti Igun Kíkà, tàbí kọ orúkọ mìíràn pẹ̀lú \"✏️ Mìíràn\"; òǹkọ̀wé kò pọn dandan. ✏️ ń ṣàtúnṣe ọ̀rọ̀ àyọlò, 🗑️ sì ń pa á rẹ́. Àwọn ọ̀rọ̀ àyọlò jẹ́ àmì ìwé tí o máa ń fà kọjá – 🎨 lókè máa ń yí i padà sí fọ́tò tàbí ògiri káàdì.",
    faq_a_room_wish_jar: "Lórí pẹpẹ nínú yàrá àṣírí, ìgò dígí kan wà fún àwọn àlá. Tẹ ìgò kékeré lórí pẹpẹ tó ga jù (tàbí Pẹpẹ > Ìgò àwọn ìfẹ́) kí o sì kọ bí o ṣe fẹ́ kí ayé rẹ rí – bí o ti fẹ́, láìsí ẹ̀tọ́ tàbí àìtọ́. Ìfẹ́ kọ̀ọ̀kan ni a ká sí bébà kan tí ó máa ń jábọ́ sínú ìgò. \"Fa bébà kan jáde\" máa ṣí ọ̀kan láìmọ̀, a sì lè ṣí bébà kọ̀ọ̀kan lọ́tọ̀. Láti ìgbà kejì tí o bá ṣí ìfẹ́ kan náà, o lè sọ ọ́ di góńgó kí o sì pín in sí ìgbésẹ̀ kéékèèké. Lẹ́ẹ̀kan lọ́sẹ̀, bébà kan tí ọ̀kan nínú àwọn ìfẹ́ rẹ wà lórí rẹ̀ máa yọ jáde pẹ̀lú ìrọ̀rùn – láìsí ìfúnpá, ìránnilétí ibi tí ò ń lọ nìkan.",
    faq_q_book_quotes: "Níbo ni mo ti lè tọ́jú ọ̀rọ̀ àyọlò láti inú ìwé tí mo fẹ́ràn?",
