    room_wish_written: "A kọ ọ́ ní {date}",
    faq_a_saved_meals_page: "Oúnjẹ tí a fi pamọ́ ní ojú-ìwé tirẹ̀: Oúnjẹ àti Ìwọ̀n > ⭐ Oúnjẹ tí a fi pamọ́ (tàbí ⭐ nínú àtòjọ). Ìwádìí lókè máa rí oúnjẹ nípa orúkọ tàbí èròjà, \"Èyí tí a lò láìpẹ́\" ń fi ohun tí o fi kún láìpẹ́ hàn, àwọn táàbù (Oúnjẹ àárọ̀, Oúnjẹ ọ̀sán, Oúnjẹ alẹ́, Ọbẹ̀…) sì ń fi àkókò kọ̀ọ̀kan ọjọ́ hàn. \"+ Òní\" máa fi oúnjẹ kún Àtẹ̀lé Oúnjẹ Ojoojúmọ́ ti òní, ní àyè òfo tó kàn. Tẹ oúnjẹ kan láti ṣàtúnṣe rẹ̀ tàbí pa á rẹ́, ＋ lókè sì máa fi tuntun kún un.",
