    presets_tab_soup: "Ọbẹ̀",
    presets_tab_sweet: "Ohun dídùn",
    faq_a_notes_sticky_look: "Àwọn àkọsílẹ̀ jẹ́ àtòjọ kúkúrú ti káàdì gíláàsì – 🎨 lókè Àkọsílẹ̀ máa ń yí ìrísí gbogbo Àkọsílẹ̀ padà: àtòjọ náà, àwọn bọ́tìnnì ọjọ́ lókè àti fèrèsé tí a ti ń kọ àkọsílẹ̀ – gíláàsì, àtòjọ mímọ́, káàdì àkọsílẹ̀ tàbí téèpù washi. Àkọsílẹ̀ tí a ń fà máa ń pa ìrísí àti àwọ̀ tirẹ̀ mọ́ gẹ́lẹ́. Tẹ ọ̀rọ̀ inú àkọsílẹ̀ kan láti ṣí i – níbẹ̀ o lè ṣàtúnṣe rẹ̀, yí àwọ̀ rẹ̀ padà, kí o sì rí ìgbà tí a kọ ọ́ kẹ́yìn. Tẹ ○ nígbà tí ó bá ti parí, × sì máa gbé e lọ sí Àkójọ (🗑️ ní ìsàlẹ̀ àtòjọ máa dá a padà). Fà á pẹ̀lú ⠿ láti yí ètò padà, láti gbé e sí ìsàlẹ̀ “Nígbà mìíràn”, tàbí sórí ọjọ́ kan lókè. ! ń sàmì sí àkọsílẹ̀ kan pé ó jẹ́ kánjúkánjú – ó máa rọra gòkè lọ sí àwọn ìlà àkọ́kọ́ pẹ̀lú àmì kékeré “Kánjúkánjú”; títẹ̀ ẹ́ lẹ́ẹ̀kan sí i yóò yọ àmì náà kúrò.",
    faq_q_notes_sticky_look: "Báwo ni mo ṣe lè ṣí àkọsílẹ̀ kan, ṣàtúnṣe rẹ̀ tàbí yọ ọ́ kúrò?",
    note_to_archive_btn: "Gbé e lọ sí Àkójọ",
    faq_a_routine_clash: "Bí ohun kan bá ti wà ní àkókò yẹn ní àwọn ọjọ́ kan náà, àṣàyàn méjì yóò hàn: \"Pààrọ̀\" – ohun tuntun gba àkókò yẹn, o sì yan àkókò mìíràn fún èyí tó wà tẹ́lẹ̀ (nígbà tí o bá ń ṣàtúnṣe ohun tó ti wà, a ó dábàá àkókò rẹ̀ àtẹ̀yìnwá, kí àwọn méjèèjì kàn pààrọ̀ ipò), tàbí \"Méjèèjì\" – àwọn méjèèjì yóò wà ní àkókò kan náà, ọ̀kan lábẹ́ èkejì. Bí àwọn ọjọ́ bá yàtọ̀ (bíi ọ̀kan Àìkú–Bọ̀, èkejì Ẹtì), a kò ní béèrè nǹkan kan.",
    faq_q_routine_clash: "Kí ló ń ṣẹlẹ̀ bí mo bá fi nǹkan sínú ìṣe ojoojúmọ́ ní àkókò tí ohun mìíràn ti wà?",
    routine_clash_both: "✌️ Méjèèjì – méjèèjì ní agogo {time}",
    routine_clash_move_btn: "Gbé e lọ kí o sì fi pamọ́",
    routine_clash_move_to: "Agogo mélòó ni kí a gbé \"{title}\" lọ?",
    routine_clash_replace: "🔄 Pààrọ̀ – kí o sì gbé \"{title}\" lọ sí àkókò mìíràn",
    routine_clash_title: "Ní agogo {time}, ohun kan ti wà tẹ́lẹ̀: {title}",
    faq_a_new_me_coffee: "Lábẹ́ àkójọ oúnjẹ òní ni àkópọ̀ kúkúrú kan wà: iye kálórì tí gbogbo oúnjẹ òní jẹ́ pọ̀, iye tó kù fún kọfí àti ohun mímu, àti bọ́tìnnì fún kọfí àti ohun mímu tí a yàn – títẹ̀ kan ń fi í kún Ohun mímu. Nínú \"Yan tó 3 tí o fẹ́ràn\" lábẹ́ àwọn bọ́tìnnì náà (àti nínú ìwé-ìbéèrè) yan ohun tí yóò hàn: omi / omi sóòdà, tíì ewéko, ohun mímu diet, dúdú / americano (~5), tíì pẹ̀lú wàrà díẹ̀ (~25), kọfí tí a fi omi ṣe pẹ̀lú wàrà tàbí wàrà ewéko tí kò ju 100 ml lọ (~50), ṣokoléètì gbígbóná fúyẹ́, wàrà gbígbóná tàbí kọfí lásán / latte (~120).",
    faq_q_new_me_coffee: "Ibo ni mo ti lè fi kọfí kún un, báwo sì ni mo ṣe lè mọ iye tó kù fún ọjọ́ náà?",
