    nm_late_ideas_none: "Díẹ̀ gan-an ló kù lónìí – tíì, omi tàbí kọfí dúdú",
    nm_late_room_line: "Nǹkan kékeré kí o tó sùn · kálórì ~{n} ló kù lónìí",
    faq_a_recipe_examples: "Lábẹ́ àwọn ìlànà tìrẹ, àwọn ìlànà àpẹẹrẹ wà: oúnjẹ àárọ̀, sàláàdì, ọbẹ̀, oúnjẹ pàtàkì, oúnjẹ ẹ̀gbẹ́, ìpanu, oúnjẹ dídùn àti oúnjẹ vegan, ọ̀kọ̀ọ̀kan pẹ̀lú àkókò ìpèsè, kálórì fún ìpín kọ̀ọ̀kan àti iye gíráàmù tí ìpín kan wọ̀n. Tẹ ìlànà kan láti ṣí i, \"Fi pamọ́ sí Àwọn Ìlànà Mi\" sì ń ṣe ẹ̀dà tìrẹ tí o lè ṣàtúnṣe. Àwọn àmì ẹ̀ka ń ṣàyọ̀, títẹ àmì kan náà lẹ́ẹ̀kan sí i sì ń fi gbogbo rẹ̀ hàn.",
    faq_a_recipe_grams: "Nínú ìlànà, lẹ́gbẹ̀ẹ́ kálórì, a kọ \"Ìpín 1 ≈ gíráàmù X\". Nínú àwọn ìlànà tìrẹ, kọ \"Gíráàmù fún ìpín kan\" (àti àkókò ìpèsè bí o bá fẹ́) sínú fọ́ọ̀mù ìlànà: méjèèjì kì í ṣe dandan, àkókò sì ń hàn lórí ìlà àwọ̀ ìlànà náà.",
