    recipes_examples_title: "Àwọn ìlànà àpẹẹrẹ",
    faq_a_recipe_scan_multi: "Bẹ́ẹ̀ni. Nínú \"Fi Ìlànà Kún\", tẹ 📷 kí o sì yan fọ́tò kan tàbí mélòó kan (tó 6; PDF náà ṣiṣẹ́). Ọ̀kọ̀ọ̀kan yóò hàn nínú àkójọ kúkúrú níbi tí o ti yan ohun tó wà nínú rẹ̀: Gbogbo rẹ̀, Èròjà tàbí Bí a ṣe ń ṣe é, \"➕ Fọ́tò mìíràn\" sì ń fi òmíràn kún un. Lẹ́yìn náà tẹ \"✨ Ṣàyẹ̀wò ìlànà náà\": AI yóò so gbogbo rẹ̀ pọ̀ di ìlànà kan, ní ṣíṣe tẹ̀léra àti láìtún ìlà kankan sọ, a sì ka á sí àyẹ̀wò kan ṣoṣo. Àwọn fọ́tò púpọ̀ tí a yàn láti 📷 Fọ́tò nínú olùrànlọ́wọ́ AI náà ń ṣí síbí pẹ̀lú.",
    faq_q_recipe_scan_multi: "Ṣé mo lè ṣàyẹ̀wò ìlànà kan láti inú fọ́tò mélòó kan, bíi èròjà àti bí a ṣe ń ṣe é lọ́tọ̀ọ̀tọ̀, tàbí ojú-ìwé méjì?",
    recipe_scan_add_more: "➕ Fọ́tò mìíràn",
    recipe_scan_part_all: "Gbogbo rẹ̀",
    recipe_scan_part_ingredients: "Èròjà",
    recipe_scan_part_steps: "Bí a ṣe ń ṣe é",
    recipe_scan_remove_photo: "Yọ fọ́tò náà kúrò",
    recipe_scan_run_btn: "✨ Ṣàyẹ̀wò ìlànà náà",
    recipe_scan_too_many: "Tó fọ́tò {n} fún ìlànà kọ̀ọ̀kan",
    faq_a_note_written_at: "Tẹ ọ̀rọ̀ àkọsílẹ̀ náà láti ṣí i. Nínú rẹ̀, lábẹ́ ọ̀rọ̀ náà, a ó rí ìgbà tí a kọ ọ́ kẹ́yìn, pẹ̀lú ọjọ́ àti àkókò gangan. Yíyí ọ̀rọ̀ náà fúnra rẹ̀ nìkan ló ń ṣe àtúnṣe èyí: fífi sí àkójọ àti dídá a padà, fífi ✓, àwọ̀ tàbí gbígbé àkọsílẹ̀ náà kò yí i padà.",
    faq_q_note_written_at: "Báwo ni mo ṣe lè rí ìgbà tí mo kọ àkọsílẹ̀ kan?",
    note_written_at: "Ìgbà tí a kọ ọ́ kẹ́yìn: {date}",
    faq_a_new_me_month: "Nínú àpò idán → Kàlẹ́ńdà oṣù: ọjọ́ kọ̀ọ̀kan ní àwọ̀ gẹ́gẹ́ bí iye oúnjẹ tí a sàmì sí, àwọn ọfà ‹ › máa ń yí oṣù padà, ní ìsàlẹ̀ kàlẹ́ńdà sì ni àròpin kálórì ojoojúmọ́ oṣù náà wà. Títẹ ọjọ́ kan máa fi iye oúnjẹ tí a sàmì sí àti iye kálórì tí a jẹ ní ọjọ́ náà hàn.",
    faq_q_new_me_month: "Níbo ni mo ti lè wo oṣù tó kọjá àti àròpin kálórì nínú New Me?",
    nm_month_avg: "Àròpin oṣù: kálórì {kcal} lójúmọ́ · ọjọ́ tí a kọ sílẹ̀: {n}",
    nm_month_day_empty: "Kò sí ohun tí a kọ sílẹ̀ ní ọjọ́ yìí.",
    nm_month_day_line: "Oúnjẹ tí a sàmì sí: {checks} · kálórì: {kcal}",
    nm_extra_line_small: "Kálórì {n} fún oúnjẹ yìí, láti inú oúnjẹ àárọ̀ kékeré – fún àpẹẹrẹ {ideas}",
    faq_a_new_me_small_breakfast: "Oúnjẹ àárọ̀ fífúyẹ́ (nǹkan bí kálórì 170): pita spelt kan (títí dé kálórì 100) pẹ̀lú ìpara tàbí wàràkàṣì, àti ẹ̀fọ́ kan – yan tó 3 tí o fẹ́ràn, fún àpẹẹrẹ ṣíbí kékeré 1 ti ṣokoléètì ìpara, ṣíbí kékeré 1 ti bọ́tà ẹ̀pà tàbí ege kan ti wàràkàṣì líle (títí dé 22%). Nítorí pé ó kéré, “Àti oúnjẹ kékeré kan sí i” máa ń bá a wá ní àkókò mìíràn (wákàtí kan àbọ̀ lẹ́yìn rẹ̀, fún àpẹẹrẹ 11:30 → 13:00 – a lè yan àkókò mìíràn): pita mìíràn àti ìpara, yogurt amuaradagba àti èso, rice cake àti wàràkàṣì, cereal àti wàrà tàbí ìdajì pita àti ẹyin – títí dé nǹkan bí kálórì 200, pẹ̀lú ✓ tirẹ̀. Ohun tó bá ṣì kù ni a pín sí àwọn oúnjẹ yòókù, oúnjẹ kọ̀ọ̀kan sì ń fi iye tí a fi kún un hàn, nítorí náà àpapọ̀ ọjọ́ náà máa wà bí ó ti wà nínú ètò. Yan án nínú ìwé-ìbéèrè, tàbí yí padà sí i fún òní nìkan pẹ̀lú 🔄 – fún àpẹẹrẹ nígbà tí oúnjẹ àárọ̀ bá pẹ́.",
    faq_q_new_me_small_breakfast: "Kí ni \"oúnjẹ àárọ̀ kékeré\" nínú àkójọ oúnjẹ New Me?",
