    weather_sky_storm: "Ìjì",
    faq_a_ai_icon: "Bẹ́ẹ̀ ni – nínú Ètò > Ìrísí àti Ìfihàn. Àfòfó rírọ̀ ni ti àìyípadà, àti pẹ̀lú Premium o tún lè yan ọpọlọ tó ń léfòó tàbí rọ́bọ́ọ̀tì.",
    faq_a_new_me_favorites: "Bẹ́ẹ̀ ni. Nínú ìwé-ìbéèrè (àti nígbà tí o bá tún kún un láti Ètò), o lè yan tó àṣàyàn 2 fún oúnjẹ kọ̀ọ̀kan. Èkíní máa hàn nínú àkójọ oúnjẹ, pẹ̀lú ìlà “tàbí” nísàlẹ̀ rẹ̀ fún èkejì – títẹ̀ ẹ́ máa yí padà sí i fún òní nìkan. Bí a kò bá sì jẹ oúnjẹ àárọ̀ lásìkò, “⏰ Lẹ́yìn náà” máa sún un sí ìgbà míì lọ́jọ́ náà, láìyí kálórì padà.",
    faq_a_theme_mode: "Àwọn àkòrí pàtàkì kan máa ń rẹwà jù nínú dúdú – Àwọ̀ omi, Aurora, Barbie àti àwọn àkòrí dídán méjèèjì – nítorí náà yíyan ọ̀kan nínú wọn máa yí ohun èlò náà sí ipò dúdú, yíyan àkòrí mìíràn èyíkéyìí (àti rọ́kẹ́ẹ̀tì náà) sì máa yí i sí ìmọ́lẹ̀. Dúdú àti Eérú-dúdú máa wà ní dúdú. O lè yí i padà nígbàkigbà lẹ́yìn náà pẹ̀lú 🌙 nínú àkójọ àṣàyàn tàbí Ipò Ìmọ́lẹ̀ nínú ètò.",
    faq_a_water_month: "Nínú àbójútó omi. Ohun kọ̀ọ̀kan nínú àkọsílẹ̀ òní máa fi àkókò tí a fi kún un hàn, \"Tábìlì oṣù\" sì máa ṣí gbogbo oṣù: ọjọ́ kọ̀ọ̀kan máa fi iye lítà tí a mu hàn (✓ nígbà tí a bá dé àfojúsùn ojoojúmọ́), títẹ ọjọ́ kan sì máa fi àwọn àkọsílẹ̀ rẹ̀ hàn pẹ̀lú àkókò wọn.",
    faq_q_ai_icon: "Ṣé mo lè yí àmì olùrànlọ́wọ́ AI padà?",
