    dev_sim_panel_title: "PM – fún ìwọ nìkan",
    faq_a_new_me_weight_optional: "Rárá. Ìwúwo lọ́wọ́lọ́wọ́ àti ìwúwo àfojúsùn nínú ìbéèrè méjèèjì kò pọn dandan. Bí a bá fi ìwọ̀n kún un lẹ́yìn náà (⚖️ Ìwúwo nínú \"Ìrìn-àjò mi\" ní New Me, tàbí nínú olùtọpinpin ìwúwo), ìlọsíwájú á bẹ̀rẹ̀ láti ìwọ̀n àkọ́kọ́.",
    faq_q_new_me_weight_optional: "Ṣé dandan ni láti kọ ìwúwo sínú New Me?",
    nm_unlock_desc: "Àkójọ oúnjẹ, àwọn ìpèníjà àti ìrìn-àjò ti ṣetán – ìgbésẹ̀ kọ̀ọ̀kan, papọ̀.",
    nm_unlock_title: "New Me ti ṣí sílẹ̀!",
    room_reveal_star: "Ìràwọ̀ tuntun kan tàn nínú awò-ìwò-ìràwọ̀ tó wà lórí òrùlé ✨",
    faq_a_room_records: "Ẹ̀rọ àwo orin wà nínú yàrá láti ìbẹ̀rẹ̀, lórí kùkùté igi lẹ́gbẹ̀ẹ́ àga ìjókòó. Àwọn àwo rẹ̀ ń ṣí àwọn fídíò ojúlówó ti àwọn orin olókìkí ńlá àwọn ọdún díẹ̀ sẹ́yìn lórí YouTube, nísàlẹ̀ wọn sì ni orin ìdákẹ́jẹ́ẹ́ márùn-ún tí ń dún níbí nínú yàrá – àwo náà ń yí nígbà tí wọ́n ń dún, \"⏹ Dúró\" sì ń pa orin.",
    faq_a_room_roof_gifts: "Wọ́n ń dé pẹ̀lú kọ́kọ́rọ́ kẹjọ. Fífọwọ́ kan awò-ìwò-ìràwọ̀ jẹ́ kí o lè wo inú rẹ̀: ojú-ọ̀run òru ní ọ̀nà tímọ́tímọ́ – fà á (tàbí lo àwọn ọfà) láti wò yíká – àwọn ìpèníjà tí o ti parí sì ń ya àkójọ ìràwọ̀ nínú rẹ̀, ìràwọ̀ kan fún ìpèníjà kọ̀ọ̀kan; fífọwọ́ kan ìràwọ̀ ń fi èwo ló jẹ́ hàn. Fífọwọ́ kan àpótí kékeré náà ń ṣí i – fún àkókò yìí ó ṣofo – fífọwọ́ kàn án lẹ́ẹ̀kan sí i sì ń tì í.",
    faq_q_room_records: "Kí ló wà lórí ẹ̀rọ àwo orin nínú yàrá àṣírí?",
    faq_q_room_roof_gifts: "Kí ni awò-ìwò-ìràwọ̀ àti àpótí tó wà lórí òrùlé?",
    room_chest_letter: "Lẹ́tà kékeré kan fún ọ",
    room_chest_letter_1: "Gbogbo ìgbésẹ̀ kékeré lójú ọ̀nà jẹ́ òótọ́ – ọ̀kọ̀ọ̀kan sì ní ìtumọ̀.",
    room_chest_letter_2: "Ṣíṣe dáradára sí ara ẹni jẹ́ apá kan ọ̀nà, kì í ṣe ìsinmi kúrò nínú rẹ̀.",
    room_chest_letter_3: "Àwọn ọjọ́ kan fúyẹ́, àwọn mìíràn wúwo. Wíwà níbẹ̀ ní méjèèjì ni agbára tòótọ́.",
    room_chest_letter_4: "A gbà ọ́ láàyè láti sinmi. Ìsinmi náà jẹ́ ìgbésẹ̀ síwájú.",
    room_chest_letter_5: "Àwọn àyípadà tó ń pẹ́ ni àwọn tó dákẹ́ – a ń kọ́ wọn lójoojúmọ́.",
    room_chest_letter_6: "Òní jẹ́ ọjọ́ rere láti yangàn – kódà díẹ̀ péré.",
    room_chest_letter_7: "Kò pọn dandan láti ṣe gbogbo rẹ̀. Ohun kékeré tó kàn nìkan.",
