    faq_a_new_me_preview: "Bẹ́ẹ̀ ni. Ojú-ìwé New Me ń bẹ̀rẹ̀ pẹ̀lú fídíò kúkúrú nípa ohun tó ń ṣẹlẹ̀ nínú rẹ̀: ìbéèrè, àwọn fìtílà inú ọ̀dẹ̀dẹ̀, àpò idán, àwọn ìpèníjà àti àwọn kọ́kọ́rọ́. Nísàlẹ̀ rẹ̀ ni gbogbo ohun tó wà nínú rẹ̀, àwòrán ọjọ́ kan àti àwọn ìdáhùn kúkúrú.",
