    ai_chat_food_edit: "✏️ Ṣàtúnṣe kálórì / protein",
    ai_chat_food_invalid: "Kálórì gbọ́dọ̀ jẹ́ nọ́ńbà tó ju 0 lọ",
    ai_chat_food_updated: "A ti ṣe àtúnṣe:",
    faq_a_ai_chat_food_fix: "Bẹ́ẹ̀ ni. Ní ìsàlẹ̀ ìdáhùn nínú ìjíròrò, tẹ ✏️ Ṣàtúnṣe kálórì / protein, yí àwọn nọ́ńbà padà kí o sì tẹ Fi Pamọ́. Ohun tí a ṣẹ̀ṣẹ̀ fi kún nìkan ló ń yí padà – kódà bí ó bá ti dara pọ̀ mọ́ ìpanu tó ti wà tẹ́lẹ̀. AI lè ṣe àṣìṣe, nítorí náà ó dára láti yẹ̀ ẹ́ wò kíákíá.",
    faq_a_new_me_home_btn: "Tí o bá ní New Me, 💎 kékeré kan lẹ́gbẹ̀ẹ́ ipò àfojúsùn ní òkè ojú-ìwé ilé ń ṣí àkójọ oúnjẹ ti òní. Àwọn oúnjẹ òní tún ń hàn nínú Ọjọ́ Mi, ọ̀kọ̀ọ̀kan pẹ̀lú ✓.",
    faq_a_routine_item_days: "Bẹ́ẹ̀ ni. Tẹ ohun náà nínú Ìlànà Mi, kí o sì yan àwọn ọjọ́ rẹ̀ ní 📅 Àwọn ọjọ́ – fún àpẹẹrẹ Ọjọ́ Ajé sí Ọjọ́ Ẹtì nìkan. Ní àwọn ọjọ́ yòókù kò ní hàn nínú Ọjọ́ Mi, kò sì ní ✓; nínú Ìlànà Mi ó ṣì wà, ó rẹ̀wẹ̀sì díẹ̀, pẹ̀lú àwọn ọjọ́ rẹ̀ lẹ́gbẹ̀ẹ́ rẹ̀. Káàdì tó ń béèrè nípa ohun kan lẹ́yìn ọjọ́ 3 láìsí ✓ ń ka àwọn ọjọ́ ti ohun náà nìkan.",
    faq_q_ai_chat_food_fix: "Ṣé mo lè ṣàtúnṣe kálórì tàbí protein lẹ́yìn tí olùrànlọ́wọ́ bá kọ oúnjẹ sílẹ̀?",
    faq_q_new_me_home_btn: "Níbo ni New Me wà lórí ojú-ìwé ilé?",
    faq_q_routine_item_days: "Ṣé ohun kan nínú Ìlànà Mi lè wà ní àwọn ọjọ́ kan nìkan?",
    routine_item_days_label: "📅 Àwọn ọjọ́",
    home_note_meal_ph: "Wá oúnjẹ tí o fi pamọ́…",
    menu_quick_search: "Ìwákiri kíákíá",
    nm_times_hint: "Ìmọ̀ràn: o lè fi àkókò tó pẹ́ jù tí o máa ń jẹ oúnjẹ kọ̀ọ̀kan sí – fún àpẹẹrẹ 9:00 tí o bá máa ń jẹun ní nǹkan bí aago 8.",
    room_game_marquee: "Lójú ọ̀nà – dúró kí o gbádùn",
    room_sand_erase_aria: "Pa ọ̀rọ̀ náà rẹ́ nípa fífi ọwọ́ pa á",
    faq_a_home_note_line: "Kọ sínú ìlà tó wà ní àárín ojú-ìwé àkọ́kọ́ kí o sì tẹ ➤ (tàbí Enter) – á fi pamọ́ sínú Àkọsílẹ̀. Tẹ 📝 ní ìbẹ̀rẹ̀ ìlà náà, á di 🛒: nígbà náà ohun tí o bá kọ á lọ sínú Àtòjọ Ọjà. Tẹ̀ ẹ́ lẹ́ẹ̀kan sí i fún 🍎: kọ lẹ́tà díẹ̀, àwọn oúnjẹ tí o fi pamọ́ tó bá mu á hàn, ìfọwọ́kàn kan sì máa kọ ọ̀kan sínú oúnjẹ ti òní. Pẹ̀lú 🎤, o lè kàn sọ ọ́.",
    faq_a_night_mode: "Ṣí àkójọ ☰ kí o sì tẹ 🌙 lókè – gbogbo áàpù á ṣókùnkùn. ☀️ ní ibi kan náà á mú ọ̀sán padà. Ó tún wà nínú Ètò, lábẹ́ Ipò Ìmọ́lẹ̀.",
    faq_q_home_note_line: "Báwo ni mo ṣe lè kọ àkọsílẹ̀ kíákíá láti ojú-ìwé àkọ́kọ́?",
    faq_q_night_mode: "Báwo ni mo ṣe lè yí padà sí ipò alẹ́?",
    menu_day_mode: "Ipò ọ̀sán",
    menu_night_mode: "Ipò alẹ́",
    faq_a_secret_room_yoga: "Ní òpin ọ̀nà inú igbó, ẹnubodè kan tí ń tàn yòò wà, àti lẹ́yìn rẹ̀, lẹ́gbẹ̀ẹ́ omi ìṣàn kan, àwọn ẹ̀dá inú igbó – Lumi, Puffi, Nixie àti Sparklet – jókòó lórí ẹní wọn ní ìdajì òbìrí, Flora, olùkọ́ yoga, sì jókòó kọjú sí wọn lórí ẹní kan ṣoṣo tí ó wà lórí òkúta. Fọwọ́ kan Flora: yóò la ojú rẹ̀, gbogbo nǹkan yóò súnmọ́ tòsí, ìjíròrò náà yóò sì bẹ̀rẹ̀ díẹ̀díẹ̀, pẹ̀lú àkókò láti kà – Flora ń béèrè bí gbogbo wọn ṣe wà, ẹ̀dá kọ̀ọ̀kan ń dáhùn ní orúkọ ara rẹ̀ (pẹ̀lú àwòrán kékeré ti ẹni tí ń sọ̀rọ̀ lẹ́gbẹ̀ẹ́ ìlà kọ̀ọ̀kan), lẹ́yìn náà ó béèrè lọ́wọ́ rẹ bí o ṣe ń rí lára pẹ̀lú àwọn tó sún mọ́ ọ. Ìjíròrò náà ń tẹ̀síwájú gẹ́gẹ́ bí ìdáhùn rẹ – àwọn ènìyàn rere, ẹnì kan tí ó ṣòro, tàbí ìdáwà díẹ̀. Ọ̀nà kọ̀ọ̀kan ń parí pẹ̀lú iṣẹ́ kékeré kan (ó lè lọ tààrà sínú Ọjọ́ Mi; nígbà tí iṣẹ́ náà bá jẹ́ láti kọ nǹkan kan, ibi wà láti kọ ọ́, a sì ń fi pamọ́ sínú ìwé-ìrántí idán) àti ìdúró kan pẹ̀lú èémí mẹ́ta papọ̀. ↩ ń padà sẹ́yìn ìgbésẹ̀ kan, ✦ sì ń bẹ̀rẹ̀ ìjíròrò tuntun. Kọ́kọ́rọ́ tó kàn ń ṣí omi ìṣàn náà: tí o bá jókòó lórí òkúta náà, gbogbo nǹkan á pòórá, ohùn omi nìkan ló kù. Tí o bá tẹ̀ lórí adágún omi, ìbéèrè kan ń jáde láti inú omi – kí ni ìwọ tòótọ́ yóò ṣe lónìí? – ìdáhùn rẹ̀ sì ń di iṣẹ́ kékeré kan nínú Ọjọ́ Mi. Àkókò ìtura ni, kì í ṣe àrọ́pò fún bíbá ògbóǹtarìgì sọ̀rọ̀.",
    faq_q_secret_room_yoga: "Kí ló ń ṣẹlẹ̀ nínú yoga inú igbó?",
    room_back_to_forest: "Padà sí ọ̀nà",
    room_back_to_yoga: "Padà sí yoga",
    room_item_waterfall: "Omi ìṣàn",
