    room_waterfall_rock_aria: "Jókòó lórí àpáta",
    room_yoga_guide_aria: "Bá Flora sọ̀rọ̀",
    yg_g_alone: "O ṣé tí o pín in. Ó máa ń ṣẹlẹ̀ sí gbogbo ènìyàn nígbà míì.",
    yg_g_alone_q: "Kí ni yóò dára lára rẹ, kódà díẹ̀ péré?",
    yg_g_critic: "Ìbáwí lè ta ni fún ìgbà pípẹ́. Ó ń sọ nípa àkókò kan – kì í ṣe nípa gbogbo ènìyàn náà.",
    yg_g_end: "O ṣé tí o wá sínú àyíká. O lè padà wá nígbàkígbà tí o bá fẹ́.",
    yg_g_gate: "Ó tọ́ láti fi ààlà sílẹ̀. Ààlà kì í ṣe ògiri – ẹnubodè ni.",
    yg_g_good: "Ó dára gan-an 💛 Ta ló ṣe ọ́ lóore ní ọ̀sẹ̀ yìí?",
    yg_g_good_msg: "Ó yẹ ká sọ fún àwọn ènìyàn rere pé wọ́n dára. Ọpẹ́ kékeré lè mú gbogbo ọjọ́ wọn dùn.",
    yg_g_hard: "O ṣé tí o sọ ọ́. Kí ló ń wọ̀ ọ́ lọ́rùn jù lọ?",
    yg_g_listen: "Kí wọ́n má gbọ́ ọ ń rẹ ni. Ohùn rẹ ṣe pàtàkì, kódà nígbà tí ó bá jẹ́ jẹ́jẹ́.",
    yg_g_new: "Àwọn ènìyàn tuntun ń bẹ̀rẹ̀ pẹ̀lú ìkíni kékeré kan. Kíláàsì, ìrìn, ẹgbẹ́ – ìgbésẹ̀ kan.",
    yg_g_old: "Ẹni tó ti mọ̀ ọ́ tẹ́lẹ̀ jẹ́ ibi tó gbóná. Ìfiránṣẹ́ kúkúrú tó.",
    yg_g_start: "Àti nísinsìnyí, ìwọ ló kàn 🌿 Báwo lo ṣe ń rí lára pẹ̀lú àwọn tó sún mọ́ ọ láìpẹ́ yìí?",
    yg_g_used: "Nígbà tí a bá ń fúnni láìrí nǹkan kan gbà padà, ohun kan nínú wa ń rẹ̀. Ó dára láti kíyèsí i.",
    yg_name_guide: "Flora",
