    yg_o_good: "Ara mi balẹ̀ pẹ̀lú wọn 💛",
    yg_o_hard: "Ẹnì kan wà tí ó ṣòro fún mi",
    yg_o_listen: "Wọn kì í tẹ́tí sí mi",
    yg_o_new: "Mọ àwọn ènìyàn tuntun",
