    yg_o_used: "Ó dà bí ẹni pé wọ́n ń lò mí",
    yg_p1_alone: "A wà níbí 💛",
    yg_p1_good: "Ó dùn mọ́ mi láti gbọ́! Ó mú ọkàn mi gbóná.",
    yg_p1_start: "Ọ̀sẹ̀ mi kún fún iṣẹ́, ṣùgbọ́n ọ̀rẹ́ rere kan pè mí ní àkókò tó yẹ gan-an.",
    yg_p2_hard: "Èmi náà ti rí bẹ́ẹ̀. Kí n kàn sọ ọ́ jáde ti ràn mí lọ́wọ́.",
    yg_p2_start: "Gbígbọ́ gbogbo ènìyàn ń ràn mí lọ́wọ́ pẹ̀lú.",
    yg_pose_child: "Báyìí ìdúró ọmọdé 🌙 Eékún sílẹ̀, iwájú orí lórí ẹní – ibi ààbò láti mí. Èémí mẹ́ta papọ̀.",
    yg_pose_heart: "Báyìí ọkàn ṣíṣí 💗 Èjìká sẹ́yìn, àyà gbòòrò. Èémí mẹ́ta papọ̀.",
    yg_pose_tree: "Báyìí ìdúró igi 🌳 Dúró gbọn-in, ẹsẹ̀ kan lórí ẹsẹ̀ kejì, ọwọ́ sókè. Èémí mẹ́ta papọ̀.",
    yg_task_good: "Fi ìfiránṣẹ́ ọpẹ́ kékeré ránṣẹ́ lónìí",
    yg_task_hard: "Kọ gbólóhùn kan tí mo fẹ́ sọ",
    yg_task_new: "Wá ibì kan láti mọ àwọn ènìyàn tuntun",
    yg_task_old: "Fi \"Mo ronú nípa rẹ\" ránṣẹ́ sí ẹnì kan",
    nm_time_hour: "Wákàtí",
    nm_time_minutes: "Ìṣẹ́jú",
    routine_time_taken: "Ohun kan ti wà ní àkókò yìí tẹ́lẹ̀: {title}",
    faq_a_new_me_times: "Nínú ìwé-ìbéèrè ní ìbẹ̀rẹ̀, àti nígbàkígbà nínú ètò New Me → \"Àkókò oúnjẹ\". Bí ìlànà rẹ bá ti ní àkókò oúnjẹ, a máa mú wọn láti ibẹ̀ – a sì lè fi oúnjẹ ìlànà pamọ́, kí oúnjẹ New Me hàn ní ipò wọn. Bí kò bá sí, o máa yan oúnjẹ mélòó lójúmọ́ (Oúnjẹ 2 + ìpanu / Oúnjẹ 2 + oúnjẹ alẹ́ fẹ́ẹ́rẹ́ / Oúnjẹ 2 + ìpanu + oúnjẹ alẹ́ fẹ́ẹ́rẹ́) àti ìgbà tí ọ̀kọ̀ọ̀kan jẹ́. Pẹ̀lú \"Oúnjẹ 2 + ìpanu\", wọ́n jẹ́ oúnjẹ ọ̀sán ní 11:30, ìpanu ní 16:00 àti oúnjẹ alẹ́ ní 19:00 (a lè yí èyíkéyìí padà). Ìwọ̀nyí ni àkókò oúnjẹ rẹ níbi gbogbo: nínú ọ̀dẹ̀dẹ̀, nínú Ọjọ́ Mi, nínú Ìlànà Mi àti nínú àwọn ìránnilétí. Ohunkóhun tí o bá yàn, kálórì ọjọ́ náà kò yí padà – ohun tí a yọ kúrò ni a pín fún àwọn oúnjẹ yòókù.",
    faq_q_new_me_times: "Báwo ni mo ṣe lè ṣètò àkókò oúnjẹ mi nínú New Me?",
    nm_times_count: "Oúnjẹ mélòó lójúmọ́?",
    nm_times_from_routine: "Bẹ́ẹ̀ ni, mú wọn láti inú ìlànà mi",
    nm_times_hide: "Fi àwọn oúnjẹ ìlànà mi pamọ́, kí oúnjẹ New Me hàn ní ipò wọn",
    nm_times_later: "Nígbà míì",
    nm_times_manual: "Rárá, yan níbí",
    nm_times_none_found: "Kò sí oúnjẹ nínú ìlànà rẹ síbẹ̀ – yan níbí iye rẹ̀ àti ìgbà.",
    nm_times_q: "Ṣé ìlànà rẹ ní àkókò pàtó fún jíjẹun?",
    nm_times_saved: "A ti fi àkókò oúnjẹ pamọ́",
    nm_times_title: "Àkókò oúnjẹ",
    faq_a_routine_exact_time: "Bẹ́ẹ̀ ni. Nígbà tí o bá ṣàlàyé ìṣe ojoojúmọ́ fún AI pẹ̀lú àkókò gangan (bíi \"16:10 ìṣòwò\"), a máa fi pamọ́ gẹ́lẹ́ bẹ́ẹ̀ – a kò ní yí i padà sí wákàtí pípé. Ohunkóhun tí a kọ sínú ìṣe ojoojúmọ́ rẹ máa ń hàn lórí pátákó nígbà gbogbo, kódà bí a kò bá yan wákàtí rẹ̀ nínú ètò àwọn wákàtí, àti pé yíyọ wákàtí tí ohun kan wà nínú rẹ̀ máa béèrè lákọ̀ọ́kọ́. O tún lè yí àkókò padà fúnra rẹ: fọwọ́ kan àkókò nínú fèrèsé nǹkan náà, kí o sì yan wákàtí àti ìṣẹ́jú.",
    faq_q_routine_exact_time: "Ṣé ìṣe ojoojúmọ́ mi lè ní àkókò gangan, bíi 16:10?",
    room_item_sand: "Kíkọ sínú iyanrìn",
    room_item_yoga: "Yoga nínú igbó",
    room_sand_ph: "Kí ni o fẹ́ jẹ́ kí ó lọ?",
    room_sand_write: "Kọ ọ́",
