    room_song_2: "Orin Ayọ̀ · Beethoven",
    room_song_3: "Canon ní D · Pachelbel",
    room_song_4: "Gymnopédie No. 1 · Satie",
    room_song_5: "Greensleeves · ìbílẹ̀",
    room_vinyl_stop: "⏹ Dúró",
    routine_hour_remove_text: "Ohun tí a kọ sí àkókò yìí yóò pa rẹ́ kúrò nínú ìṣe ojoojúmọ́: {title}",
    routine_hour_remove_title: "Yọ {time} kúrò?",
    faq_a_routine_ai: "Nínú Ìlànà Mi, ṣí ⚙️ (tàbí ➕) kí o sì tẹ \"Ìlànà tuntun pẹ̀lú AI\": ṣàpèjúwe ìlànà náà pẹ̀lú ọ̀rọ̀ tí ó rọrùn – fún àpẹẹrẹ \"jíjí ní agogo 7, eré ìdárayá ní agogo 8, iṣẹ́ títí di agogo 17\" – AI yóò sì ṣẹ̀dá táàbù tuntun pẹ̀lú àwọn wákàtí àti àwọn iṣẹ́. Bí ọ̀rọ̀ náà bá sọ àwọn ọjọ́ (\"ní àwọn ọjọ́ iṣẹ́\"), táàbù náà máa ṣí ní àwọn ọjọ́ náà, àwọn ìlànà tí ó yàtọ̀ fún àwọn ọjọ́ tí ó yàtọ̀ sì máa di táàbù ọ̀tọ̀ọ̀tọ̀. Lẹ́yìn náà a lè ṣàtúnṣe gbogbo nǹkan bí ó ti máa ń rí.",
    faq_a_routine_daysoff: "Nínú Ìlànà Mi, tẹ ➕ lẹ́yìn náà \"Àwọn ọjọ́ ìsinmi\": yan àwọn ọjọ́ (fún àpẹẹrẹ Àbámẹ́ta àti Àìkú) àti ìlànà ní àwọn ọjọ́ náà – kò sí ètò (ó wà ní òfo), ìlànà tìrẹ, tàbí sọ fún AI ohun tí o ń ṣe kí ó kọ́ ọ. Àwọn ọjọ́ ìsinmi ní táàbù tiwọn, ní àwọn ọjọ́ náà Ìlànà Mi àti Ọjọ́ Mi sì ń fi táàbù yẹn nìkan hàn.",
    faq_q_routine_ai: "Báwo ni mo ṣe lè ṣẹ̀dá ìlànà pẹ̀lú AI?",
    faq_q_routine_daysoff: "Báwo ni mo ṣe lè ṣètò àwọn ọjọ́ ìsinmi nínú Ìlànà Mi?",
    routine_add_ai: "Ìlànà tuntun pẹ̀lú AI",
    routine_add_daysoff: "Àwọn ọjọ́ ìsinmi",
    routine_ai_create: "Ṣẹ̀dá ìlànà náà",
    routine_ai_default_name: "Ìlànà tuntun",
