    routine_daysoff_own: "Ìlànà tèmi",
    routine_daysoff_pick_days: "Yan ó kéré tán ọjọ́ kan",
    routine_daysoff_what: "Kí sì ni ìlànà ní àwọn ọjọ́ náà?",
    routine_daysoff_which: "Àwọn ọjọ́ wo?",
    faq_a_secret_room_diary: "Ìwọ nìkan. A máa ń fi àwọn ojú-ewé ìwé ìrántí pamọ́ sínú àkáǹtì rẹ, nítorí náà wọ́n wà lórí gbogbo ẹ̀rọ rẹ, kò sì sí ẹlòmíì tí ó lè rí wọn. Ìwé-ìrántí idán tí ó wà lórí tábìlì ìkọ̀wé nínú yàrá àṣírí ń ṣí i, bẹ́ẹ̀ náà sì ni ìwé-ìrántí tí ó wà ní igun orin. Lábẹ́ ojú-ewé tuntun, tábìlì oṣù kan tí a ká wà: àmì kékeré kan máa fi gbogbo ọjọ́ tí ojú-ewé wà hàn, fífọwọ́ kan ọjọ́ kan sì máa ṣí àwọn ojú-ewé rẹ̀ – níbẹ̀ o tún lè pa ojú-ewé kan rẹ́. Nígbà tí ìwé-ìrántí bá ti ṣí, a tún lè fi kún àkójọ àṣàyàn àkọ́kọ́ – pẹ̀lú ìyípadà tó wà nínú ìwé-ìrántí fúnra rẹ̀ tàbí nínú Ètò New Me.",
    faq_a_secret_room_places: "Ẹnu-ọ̀nà kọ̀ọ̀kan ní ẹnubodè igbó máa ń ṣí pẹ̀lú kọ́kọ́rọ́ tirẹ̀. Lẹ́yìn wọn: ìloro tí ó kọjú sí òkun (lórí tábìlì kékeré, àtùpà Aladdin – fọwọ́ kàn án, ẹ̀mí igbó kan yóò sì jáde láti inú rẹ̀ nínú ìkùukùu idán, yóò yípo ká, yóò sì bẹ̀rẹ̀ ìjíròrò nípa ìfẹ́ ọkàn rẹ – wo “Kí ni ẹ̀mí inú àtùpà náà ń ṣe?”), gìtá àti ìwé-ìrántí (gìtá náà ń dún orin kúkúrú tí ó tura, ó sì ń dúró fúnra rẹ̀, ọ̀kọ̀ọ̀kan nínú àwo orin mẹ́ta tí a so kọ́ sára igi sì ń dún orin idán tirẹ̀ – fọwọ́ kàn án lẹ́ẹ̀kan sí i láti dá a dúró – ìwé-ìrántí tí ó wà lórí kùkùté igi sì wà fún kíkọ), yàrá mímí (adágún omi tó dákẹ́ rọ́rọ́ nígbà tí oòrùn ń wọ̀ – àtùpà lótùsì kan léfòó lórí omi: fọwọ́ kàn án, kọ ìfẹ́ ọkàn kan, yóò sì léfòó lọ pẹ̀lú rẹ̀, jìnnà sẹ́yìn sínú adágún; pẹ̀lú ọ̀pá idán o lè kọ ohun tí o fẹ́ jẹ́ kí ó lọ sínú iyanrìn, yóò sì wà níbẹ̀ títí tí o fi máa fi ìka pa á rẹ́) àti ọ̀nà inú igbó (ó máa ń ṣí ní òru, fífọwọ́ kan àwọn àtùpà sì ń yí i padà sí ọ̀sán; àga gígùn wà fún ìjókòó, fífọwọ́ kan àmì náà sì máa mú un súnmọ́ – pátákó tí ìbéèrè kékeré mẹ́fà wà lórí rẹ̀ láti fi àmì sí). Ẹnu-ọ̀nà tí a tì máa fi iye kọ́kọ́rọ́ tí ó kù hàn. Ní òpin ọ̀nà náà, ẹnubodè kan tí ń tàn yòò ń mú ni lọ sí yoga lẹ́gbẹ̀ẹ́ omi ìṣàn – àti láti ibẹ̀, sí omi ìṣàn fúnra rẹ̀.",
