    ai_chat_working_food: "Ìṣẹ́jú kan, mò ń ka kálórì…",
    ai_chat_working_schedule: "Ìṣẹ́jú kan, mò ń fi kún kàlẹ́ńdà…",
    ai_chat_working_table: "Ìṣẹ́jú kan, mò ń ṣe tábìlì náà…",
    dev_weather_preview_label: "Àyẹ̀wò – lórí àkọọ́lẹ̀ rẹ nìkan:",
    faq_a_ai_chat: "Tẹ̀ bọ́tìnnì olùrànlọ́wọ́, ìfọ̀rọ̀wérọ̀ kan yóò sì ṣí. Yan ohun tí o fẹ́ ṣe – nǹkan kan fún kàlẹ́ńdà, ohun tí o jẹ, fọ́tò ìlànà oúnjẹ tàbí tábìlì tuntun – tàbí kàn kọ̀wé, olùrànlọ́wọ́ yóò sì mọ ohun tí o fẹ́. O tún lè tẹ 🎙️ kí o sì sọ̀rọ̀ dípò títẹ̀ ọ̀rọ̀. Fún kàlẹ́ńdà, o lè yan lẹ́ẹ̀kan, lọ́sọ̀ọ̀sẹ̀ tàbí lójoojúmọ́. Ìdáhùn náà ń dé sínú ìfọ̀rọ̀wérọ̀ náà, láti ibẹ̀ o sì lè tẹ̀síwájú sí nǹkan mìíràn tàbí ṣí kàlẹ́ńdà / ohun tí o jẹ.",
    faq_a_new_me_hall: "New Me ń bẹ̀rẹ̀ ní ẹnubodè igbó idán kan, gbogbo ẹnu-ọ̀nà inú rẹ̀ sì jẹ́ ibì kan: ilẹ̀kùn róbótó inú igi ràbàtà ń wọ inú yàrá àṣírí, ìtì igi tí inú rẹ̀ ṣófo ń lọ sí ìloro tí ó kọjú sí òkun, ilé olú ń lọ sí gìtá àti ìwé-ìrántí, ọ̀ṣọ́ ẹnu-ọ̀nà kékeré ti igi wílò ń lọ sí yàrá mímí, ọ̀ṣọ́ ẹnu-ọ̀nà ńlá ti igi wílò ń lọ sí ọ̀nà inú igbó, ọ̀ṣọ́ ẹnu-ọ̀nà òdòdó tí ó ní àkàbà sì ń gòkè lọ sí òrùlé ìràwọ̀ nígbà tí òrùlé náà bá ṣí. Àgádágodo wà lára ẹnu-ọ̀nà tí a tì. Ẹ̀dá-ìtàn rẹ, Sky, ń léfòó lórí ọ̀nà náà, àwọn bọ́tìnnì eré sì yí i ká: iṣẹ́ tó kàn, ìpèníjà ọ̀sẹ̀, àpò idán tí ó ní gbogbo New Me, máàpù ayé àti àwọn irinṣẹ́. Fífọwọ́kan àwọn kọ́kọ́rọ́ ní òkè ń ṣàlàyé bí a ṣe ń rí kọ́kọ́rọ́ gbà.",
    faq_a_new_me_routine_meals: "Nígbà tí a bá ṣètò oúnjẹ nínú New Me, tí Ìlànà Mi náà sì ní oúnjẹ, New Me máa béèrè bóyá kí a fi wọ́n pamọ́ kí a sì fi oúnjẹ New Me hàn ní ipò wọn – kí ohunkóhun má baà hàn lẹ́ẹ̀mejì. Ìlànà Mi á wá fi oúnjẹ New Me hàn ní àkókò wọn, pẹ̀lú 💎 àti ✓ (títẹ orúkọ oúnjẹ kan ń ṣí fèrèsé láti yan oúnjẹ mìíràn tàbí láti yí àkókò rẹ̀ padà, níbẹ̀ gan-an lórí ìlànà). Kò sí ohun tí a ń pa rẹ́: wọ́n máa padà láti ⚙️ Ètò New Me → Oúnjẹ nínú ìlànà, tàbí nípa pípa “Ṣe ìbámu pẹ̀lú New Me” nínú ⚙️ Ìlànà Mi. Láìsí New Me tó ń ṣiṣẹ́, wọ́n máa padà fúnra wọn.",
    faq_a_room_computer: "Ìfọ̀rọ̀wérọ̀ kékeré ni, tí ó ń bẹ̀rẹ̀ pẹ̀lú “Báwo ni ọjọ́ rẹ ṣe ń lọ títí di ìsinsìnyí?” – ó dára, ọwọ́ dí tàbí ó le – tí ó sì ń bá ọ lọ ní ìgbésẹ̀ kọ̀ọ̀kan, títí dé iṣẹ́ kékeré kan ní òpin (tí ó tún lè lọ tààrà sí Ọjọ́ Mi). A lè tẹ̀ àwọn ìdáhùn tàbí kọ wọ́n bí a ṣe fẹ́ – ohun tí a kọ máa so mọ́ ìdáhùn tó sún mọ́ ọ jù. “↩ Padà” ń padà ní ìgbésẹ̀ kan kí o lè dáhùn lọ́nà mìíràn, “Ìfọ̀rọ̀wérọ̀ tuntun” sì ń bẹ̀rẹ̀ láti ìbẹ̀rẹ̀ nígbàkígbà. Lẹ́yìn ọjọ́ tí ọwọ́ dí tàbí tí ó le, o lè padà sí kọ̀ǹpútà lẹ́yìn náà ní ọjọ́ kan náà: “Mo ti padà...” ń tẹ̀síwájú ìfọ̀rọ̀wérọ̀ náà. Iná àwọ̀ ewé nísàlẹ̀ ń pa kọ̀ǹpútà, ó sì ń tàn án. Àwọn ohun tí a yàn nìkan la ń tọ́jú, lórí ẹ̀rọ yìí nìkan, títí di òpin ọjọ́ nìkan.",
    faq_q_ai_chat: "Báwo ni mo ṣe lè bá olùrànlọ́wọ́ sọ̀rọ̀?",
