    dictation_btn_aria: "Sọ̀rọ̀, á sì kọ ọ́",
    dictation_mic_denied: "Wọ́n ti dí máíkírófóònù – gbà á láàyè láti 🔒 lẹ́gbẹ̀ẹ́ àdírẹ́sì nínú aṣàwákiri, tàbí nínú ètò fóònù",
    faq_a_dictation: "Bẹ́ẹ̀ ni – fọwọ́ kan máíkírófóònù 🎤 ní igun àkọsílẹ̀ kíákíá tàbí ojú-ìwé kíkọ nínú ìwé àkọsílẹ̀, kí o sì sọ̀rọ̀: àwọn ọ̀rọ̀ á máa kọ ara wọn bí o ṣe ń sọ̀rọ̀, ní èdè áàpù. Fọwọ́ kàn án lẹ́ẹ̀kan sí i láti dá a dúró. Ní ìgbà àkọ́kọ́, aṣàwákiri á béèrè àṣẹ láti lo máíkírófóònù. Ó ń ṣiṣẹ́ lórí Chrome / Android àti Safari lórí iPhone. Lórí kọ̀mpútà o nílò máíkírófóònù àti aṣàwákiri bí Chrome, Edge tàbí Safari – bí nǹkan kan bá kù, ìfiránṣẹ́ náà máa sọ ohun tí ó jẹ́ gan-an.",
    faq_q_dictation: "Ṣé mo lè sọ̀rọ̀ dípò kí n tẹ̀ ẹ́?",
    faq_a_secret_room: "Yàrá kan tó jẹ́ tìrẹ nìkan, nínú New Me – ilé kan tí ó wà nínú igi ràbàtà kan. Ògiri kan ni o ń rí ní ìgbà kan, o sì ń yí pẹ̀lú àwọn ọfà (tàbí nípa fífà). Kọ́kọ́rọ́ àkọ́kọ́ ń dé lẹ́yìn ✓ lórí oúnjẹ ní ọjọ́ 3 ọ̀tọ̀ọ̀tọ̀, ó sì ń ṣí ilẹ̀kùn – pẹ̀lú gbogbo yàrá: kọ̀ǹpútà, eré, ẹ̀rọ àwo orin, pẹpẹ tí ilé-ìkàwé wà nínú rẹ̀ àti ológbò. Lẹ́yìn náà, ìpèníjà kọ̀ọ̀kan tó parí (ìpèníjà ọ̀sẹ̀ náà pẹ̀lú) ń fún ọ ní kọ́kọ́rọ́ tó ń ṣí ibi tó kàn: òrùlé ìràwọ̀, ìloro tí ó kọjú sí òkun, gìtá àti ìwé-ìrántí, yàrá mímí, ọ̀nà inú igbó pẹ̀lú yoga, omi ìṣàn àti ìyàlẹ́nu kan lórí òrùlé – ìpèníjà kẹjọ sì ń mú ìgò kan wá láti inú òkun, pẹ̀lú lẹ́tà láti ìgbà àtijọ́ nínú rẹ̀. Nígbà tí nǹkan bá ṣí, ọfà kan ń fi ọ̀nà hàn. Ilẹ̀kùn kékeré tí ó wà ní ìsàlẹ̀ ẹ̀rọ eré náà ń ṣí pẹ̀lú – fún ìgbà díẹ̀, àpótí tí ó wà lẹ́yìn rẹ̀ ṣófo. Lórí òrùlé ìràwọ̀, ìràwọ̀ tí a fọwọ́ kàn ń jábọ́ bí ìràwọ̀ tó ń bọ́, ológbò sì jókòó lórí ìrọ̀rí.",
