    settings_weather_hint: "Òjò, ìkùukùu tàbí yìnyín ní ẹ̀yìn ojú-ìwé àkọ́kọ́, gẹ́gẹ́ bí ojú ọjọ́ ibi tí o wà. Ibi tí o wà ní àsọtẹ́lẹ̀ máa wà lórí ẹ̀rọ yìí nìkan, a sì ń ṣàyẹ̀wò rẹ̀ nípasẹ̀ olupin wa lọ́dọ̀ MET Norway.",
    settings_weather_label: "Ojú ọjọ́ ní ojú ọ̀run ojú-ìwé àkọ́kọ́",
    weather_failed: "A kò lè ṣàyẹ̀wò ojú ọjọ́ báyìí.",
    weather_location_denied: "Kò sí ààyè sí ibi tí o wà – gbà á láàyè nínú ètò aṣàwákiri, kí o sì gbìyànjú lẹ́ẹ̀kan sí i.",
    faq_a_home_focus: "Tẹ ◎ ní òkè ojú-ìwé àkọ́kọ́: gbogbo nǹkan á pòórá àyàfi nǹkan kan fún báyìí – ohun tó wà ní wákàtí yìí, tàbí ohun tó kàn nínú àtòjọ òní – pẹ̀lú ✓ ńlá kan, àti Àkọsílẹ̀ Kíákíá. Lẹ́yìn ✓, ohun tó kàn á fara hàn. Tẹ 'Ipò àfojúsùn ✕' lókè kí gbogbo nǹkan padà.",
    faq_a_home_search: "Ṣí àkójọ ☰ – ìwákiri wà lókè pátápátá. Tẹ ó kéré tán lẹ́tà 2: àbájáde á wá láti inú àkọsílẹ̀ rẹ, àtòjọ ọjà, kàlẹ́ńdà, ìlànà oúnjẹ, ìwé àkọsílẹ̀ (àkọlé àti ọ̀rọ̀ ojú-ìwé), àfojúsùn, tábìlì àti ìwé rẹ, tí a ṣètò ní irú wọn – tẹ ọ̀kan láti lọ tààrà síbẹ̀.",
    faq_a_my_day: "Ọjọ́ Mi kó ohun tí ó jẹ́ Ìwòye Òní àti Ìlànà Mi tẹ́lẹ̀ jọ sórí ìlà àkókò kan. Ní ìsàlẹ̀ ojú-ìwé àkọ́kọ́, o máa rí iye tí a ti ṣe, ohun tó wà báyìí tàbí èyí tó kàn (pẹ̀lú ✓ kíákíá), àti ife omi kan pẹ̀lú +1 lẹ́gbẹ̀ẹ́ àkọlé. Tẹ̀ ẹ́ (tàbí fà á sókè) láti ṣí gbogbo ọjọ́ náà: lókè ni àwọn nǹkan tí kò ní àkókò, lẹ́yìn náà gbogbo nǹkan ní wákàtí-wákàtí – iṣẹ́, ìṣẹ̀lẹ̀ àti ìpàdé láti kàlẹ́ńdà, àwọn àkókò tó dúró ní ọ̀sọ̀ọ̀sẹ̀, ìlànà òní, àwọn ìgbésẹ̀ kékeré ti àwọn góńgó rẹ àti oúnjẹ New Me – pẹ̀lú ìlà kan fún báyìí. Ṣàyọ̀ ní Iṣẹ́, Ìlànà tàbí Ìpàdé àti ìṣẹ̀lẹ̀. ✓ níbí jẹ́ ✓ kan náà bí ibòmíràn (Ìlànà Mi, Àwọn Góńgó Mi, kàlẹ́ńdà), ó sì ń mú òdòdó daisy kan yọ ní igun. 'Ṣàtúnṣe ìlànà' ń ṣí Ìlànà Mi (ó tún wà nínú àkójọ ☰), '＋ Fi kún fún òní' sì ń fi iṣẹ́ kan kún fún òní. Títẹ àkọlé \"Ọjọ́ Mi\" (tàbí ìlà kékeré lókè) máa tì í padà.",
