    apptour_g_today_text: "Àwọn ìgbésẹ̀ kékeré òní ti gbogbo góńgó rẹ, ọ̀kọ̀ọ̀kan pẹ̀lú ✓ kíákíá. Wọ́n tún ń hàn nínú Ọjọ́ Mi.",
