    faq_a_new_me_tour: "Ní kété lẹ́yìn tí o bá rà á tí o sì dáhùn ìbéèrè kúkúrú, ìrìn-àjò ìfihàn kúkúrú máa fi eré náà hàn: ìlà òkè, iṣẹ́ tó kàn, ìpèníjà ọ̀sẹ̀, àpò idán àti ilẹ̀kùn 1 sí yàrá àṣírí. A lè wò ó lẹ́ẹ̀kan sí i nígbàkígbà láti ⚙️ Ètò > 🧭 Ìrìn-àjò ìfihàn New Me – níbẹ̀ náà ni a ti lè yí orúkọ kíkún láti inú ìbéèrè padà. Kí o tó rà á, New Me máa fi 🔒 hàn nínú àkójọ, tí o bá sì tẹ̀ ẹ́, ojú-ìwé tó ní gbogbo ohun tó wà nínú rẹ̀ máa ṣí.",
