    faq_a_new_me_advanced: "Ipò ìlọsíwájú máa ń ṣí pẹ̀lú ẹ̀bùn, lẹ́yìn gbogbo ìpèníjà 20, a sì lè tàn án tàbí pa á nínú 🎁 Ẹ̀bùn rẹ. Ó fún New Me ní ìrísí wúrà, kíkọ́ àkójọ oúnjẹ ní òmìnira – ìpààrọ̀ kọ̀ọ̀kan máa ń fi gbogbo àṣàyàn hàn láìsí ààlà kálórì – àti ojú-ìwé 📊 Ìṣirò tó jinlẹ̀: kálórì ọjọ́ 30 tó kọjá ní ìfiwéra pẹ̀lú ètò, ọjọ́ rere gẹ́gẹ́ bí ọjọ́ ọ̀sẹ̀, àṣà ìwúwo pẹ̀lú àmọ̀tẹ́lẹ̀ ìgbà tí a ó dé àfojúsùn, àròpín àyẹ̀wò ìrọ̀lẹ́ àti ìtàn àwọn ìpèníjà.",
