    nm_gift_locked_view: "Ẹ̀bùn yóò ṣí lẹ́yìn gbogbo ìpèníjà {n} – ó ku {left}.",
    nm_gift_intro: "Gbogbo ìpèníjà {n}, ìgbésẹ̀ kan lẹ́yìn òmíràn. Èyí ni ohun tó ń dúró:",
    nm_gift_title: "Ẹ̀bùn rẹ",
    faq_a_new_me_letter_gift: "Ní ìbẹ̀rẹ̀ New Me (tàbí lẹ́yìn náà, nínú Àwọn ìpèníjà) a lè kọ lẹ́tà sí ara rẹ ní ọjọ́ iwájú. Lẹ́yìn tí a bá ti dì í, a kò lè kà á tàbí ṣàtúnṣe rẹ̀ títí yóò fi ṣí: nínú ìgò láti inú òkun nínú yàrá àṣírí, tàbí ní òpin gbogbo ìpèníjà 20 – níbi tí ẹ̀bùn kan ti ń dúró pẹ̀lú.",
    faq_q_new_me_letter_gift: "Kí ni lẹ́tà láti ìgbà àtijọ́?",
    faq_a_new_me_challenges: "🏆 Àwọn ìpèníjà ní ìpèníjà 20: ńlá 10 (bí ọjọ́ 5 láìsí ṣúgà, ọ̀sẹ̀ kan láìsí káàbù, tàbí dín 4 kg kù ní oṣù kan – àìtó kálórì, eré-ìmárale àti láìsí ṣúgà lójoojúmọ́) àti kékeré 10 – àwọn àṣà kékeré fún ọ̀sẹ̀ kan, bí kọfí olóòórùn sinamọ́nì láìsí ṣúgà. Nígbà tí a bá yan ìpèníjà, a ó béèrè ìgbà tí a ó bẹ̀rẹ̀: òní, ọ̀la, ọ̀sẹ̀ tó ń bọ̀ tàbí ọjọ́ mìíràn. Ìpèníjà ńlá kan àti kékeré kan lè lọ papọ̀. Ìpèníjà tí ń lọ máa ń hàn lókè àkójọ oúnjẹ àti nínú Ọjọ́ Mi, pẹ̀lú ✓ fún ọjọ́ náà. Ọ̀sẹ̀ kọ̀ọ̀kan ìpèníjà ní ọjọ́ ìsinmi kan (🍕) tí kò ní já a, ọjọ́ tí a kò sàmì sí sì ka sí ọjọ́ ìsinmi – a lè sàmì sí òní àti àná. Àwọn ọjọ́ kan máa ń sàmì fúnra wọn: eré-ìmárale ìṣẹ́jú 20 nínú Àkọsílẹ̀ Eré-ìmárale, tàbí oúnjẹ inú àkójọ pẹ̀lú ✓. Ìpèníjà kọ̀ọ̀kan ní ⓘ tí ó ṣàlàyé ohun tí ó ń kà gan-an (fún àpẹẹrẹ, àkójọ kíkún kábọ́hááídírétì) – nínú ìpèníjà fúnra rẹ̀ àti lẹ́gbẹ̀ẹ́ rẹ̀ nínú Ọjọ́ Mi. Lábẹ́ wọn, 🌱 Ìdàgbàsókè ara ẹni ní ìpèníjà kékeré 48 fún ọ̀sẹ̀ kan (wọn kò sí lára 20 náà) – wo “Kí ni ìpèníjà ọ̀sẹ̀?”.",
    faq_q_new_me_challenges: "Báwo ni àwọn ìpèníjà inú New Me ṣe ń ṣiṣẹ́?",
