    nm_tile_challenges: "Àwọn ìpèníjà",
    faq_a_workout_calories: "Bẹ́ẹ̀ni. Eré ìdárayá kọ̀ọ̀kan ń gba ìṣirò kálórì tí a jó – gẹ́gẹ́ bí irú rẹ̀, àkókò rẹ̀ àti ìwúwo rẹ tó kẹ́yìn (fún sísáré àti kẹ̀kẹ́ pẹ̀lú ìyára, tí a bá kọ ijìnnà). Ó ń hàn nínú àtòjọ eré ìdárayá àti àkópọ̀ oṣù (Tí a jó), a sì ń fi kún ìnáwó kálórì ọjọ́ náà: nínú Àtẹ̀lé Oúnjẹ Ojoojúmọ́, Ìwọ̀n Kálórì àti Ìwúwo àti òrùka New Me. Ìṣirò ni, nítorí náà ó ní ~.",
    faq_q_workout_calories: "Ṣé eré ìdárayá ń wọ inú kálórì ọjọ́ mi?",
    faq_a_new_me_flexible_menu: "Bẹ́ẹ̀ ni. Nínú ìbéèrè àti ètò, a yan iye oúnjẹ lójoojúmọ́ – Oúnjẹ 2 + ìpanu / Oúnjẹ 2 + oúnjẹ alẹ́ fẹ́ẹ́rẹ́ / Oúnjẹ 2 + ìpanu + oúnjẹ alẹ́ fẹ́ẹ́rẹ́ – àti pé ➖ lórí káàdì oúnjẹ kan máa yọ ọ́ kúrò (ó kéré tán 3 máa kù); '➕ Dá a padà' máa dá a padà. Ọ̀nàkọnà, kálórì ọjọ́ náà kò yí padà: ohun tí a yọ ni a pín fún àwọn oúnjẹ yòókù, àti lábẹ́ oúnjẹ kọ̀ọ̀kan a kọ iye tí a fi kún un àti ohun tí a lè fi kún un. ✏️ Ṣàtúnṣe lórí oúnjẹ kan máa ṣí ọ̀rọ̀ rẹ̀ – yí ohun tí o bá fẹ́ padà (bí àpẹẹrẹ láìsí búrẹ́dì tàbí ẹyin kan sí i) àti pé AI máa ṣírò kálórì àti èròjà protein lẹ́ẹ̀kan sí i. 🔄 Pààrọ̀ máa fúnni ní àṣàyàn láti inú àkójọ oúnjẹ, ⭐ Tí a fi pamọ́ àti ✨ Kọ ọ́; ìyípadà kọ̀ọ̀kan lè jẹ́ fún òní nìkan tàbí láti ìsinsìnyí lọ. Àti ní ìparí 'Gbogbo ọjọ́' ni ➕ Fi oúnjẹ kún un wà – kọ ohun tí a jẹ lẹ́yìn àkójọ oúnjẹ, AI á ṣírò rẹ̀ á sì fi kún òní (✕ máa pa á rẹ́).",
    faq_q_new_me_flexible_menu: "Ṣé mo lè yí iye oúnjẹ padà nínú New Me, tàbí jẹ oúnjẹ tèmi?",
