    faq_a_goal_tasks_peek: "Oríṣi mẹ́ta: àwọn iṣẹ́ ojoojúmọ́ ti ìpèníjà ọjọ́ tó ń lọ lọ́wọ́ (àpẹẹrẹ 'Kò sí búrẹ́dì tàbí ìrẹsì') – wọ́n ń hàn lójoojúmọ́ títí ìpèníjà náà yóò fi parí, ✓ níbẹ̀ sì ń sàmì sí ọjọ́ náà nínú góńgó (àti ní ìdàkejì); 📅 àwọn ibùdó góńgó tí o ti ṣètò – ní ọjọ́ wọn, àti nínú kàlẹ́ńdà pẹ̀lú; àti 👣 ìgbésẹ̀ kékeré ti góńgó mìíràn èyíkéyìí – ṣètò rẹ̀ nígbà tí o bá ń fi góńgó kún tàbí tí o bá ń ṣàtúnṣe rẹ̀ (lójoojúmọ́, tàbí lọ́sọ̀ọ̀sẹ̀ ní ọjọ́ tí o yàn). Àwọn ìgbésẹ̀ kan náà ni wọ́n pẹ̀lú àwọn tó wà nínú 'Àwọn ìgbésẹ̀ kékeré òní' lókè Àwọn Góńgó Mi, ọ̀kọ̀ọ̀kan pẹ̀lú àmì góńgó rẹ̀. +1 tí o kọ sílẹ̀ ní ọjọ́ náà máa ń sàmì sí ìgbésẹ̀ kékeré náà fúnra rẹ̀ (bákan náà ni ìwúwo, tí ìgbésẹ̀ kékeré náà bá jẹ́ wíwọn ìwúwo fúnra rẹ̀).",
