    nm_drink_saved_empty_hint: "Tẹ ☆ láti fi ohun mímu kan pamọ́ bí ohun mímu déédéé – yóò hàn níbí, a sì lè fi kún un pẹ̀lú títẹ̀ ẹ̀ẹ̀kan.",
