    auth_consent_label: "Mo ti ka {terms} àti {privacy}, mo sì gbà wọ́n, ọjọ́-orí mi sì jẹ́ ọdún 16 tàbí jù bẹ́ẹ̀ lọ.",
    nm_bonus_sub: "Àkọsílẹ̀ kúkúrú nípa wíwọn ìwúwo, kíkọjá àfojúsùn, àti jíjẹun níta",
    nm_bonus_label: "Ẹ̀bùn",
    nm_shortcut_title: "New Me – Oúnjẹ mi lónìí",
    nm_remove: "Yọ kúrò",
    nm_split_line: "Ètò {plan} · Ohun mímu {drinks} · Àfikún {extra}",
    nm_extras_hint: "Láti Àtẹ̀lé Oúnjẹ Ojoojúmọ́ àti àfikún kíákíá – a ti kà á mọ́ òrùka náà.",
    nm_extras_title: "Ohun tí a tún jẹ lónìí",
    nm_drinks_total: "{n} / ~{kcal} kcal",
    nm_drink_missing: "Tẹ orúkọ ohun mímu àti kálórì rẹ̀",
    nm_drink_more: "+ Ohun mímu mìíràn",
    nm_drink_add: "Fi kún un",
    nm_drink_name_ph: "Ohun mímu (bí àpẹẹrẹ omi èso)",
    nm_drinks_hint: "Kàn tẹ orúkọ ohun mímu náà – a ń ṣírò kálórì fúnra rẹ̀, a sì lè yí nọ́ńbà náà padà.",
    nm_slot_drinks: "Ohun mímu",
    faq_a_new_me_tracking: "Tẹ iṣẹ́ tó kàn ní òkè New Me, lẹ́yìn náà tẹ ✓ Mo jẹun láti sàmì sí i pé a ti jẹ oúnjẹ tó kàn – gbogbo àkójọ oúnjẹ pẹ̀lú ✓ fún oúnjẹ kọ̀ọ̀kan wà nínú Gbogbo ọjọ́, ní ẹ̀gbẹ́, àwọn oúnjẹ òní sì tún hàn nínú Ọjọ́ Mi lórí ojú-ìwé ilé – títẹ̀ ọ̀kan níbẹ̀ (tàbí gbígbé eku lé e lórí) ń fi ohun tí a ó jẹ hàn ní pàtó, pẹ̀lú ✓ àti 'Pààrọ̀'. Gbogbo rẹ̀ ń bá Àtẹ̀lé Oúnjẹ Ojoojúmọ́ mu: oúnjẹ ètò, ohun mímu àti ohunkóhun tí o bá fi kún un níbòmíràn (bí àpẹẹrẹ kọfí láti àfikún kíákíá) ni a ń kà papọ̀ nínú New Me àti nínú Ọjọ́ Mi – a kò ní kọ ohunkóhun tí o ti tẹ̀ tẹ́lẹ̀ lé lórí, yíyọ ✓ kúrò sì ń yọ apá ti New Me nìkan. Nígbà tí a bá ti sàmì sí gbogbo oúnjẹ òní, ayẹyẹ kékeré kan máa ń wáyé. Lábẹ́ 'Ohun mímu', fi àwọn ohun mímu ọjọ́ náà kún un – gbogbo wọn papọ̀ tó ~150 kcal, ìyẹn ni nǹkan bí ohun mímu 3 tí ọ̀kọ̀ọ̀kan kò ju ~50 kcal lọ. Kàn tẹ̀ orúkọ ohun mímu náà, AI yóò sì kún kálórì náà fúnra rẹ̀. Àwọn ìlà méjì ti kọfí/tíì tún ní àyè 'Wàrà? Èló ni?' (bí àpẹẹrẹ 'díẹ̀' tàbí '50 ml'), a ó sì ṣe àtúnṣe ìṣirò náà; a lè yí nọ́ńbà náà padà ṣáájú fífi kún un àti lẹ́yìn náà pẹ̀lú. Ohun mímu tí ó ní orúkọ àti kálórì ni a ó fi pamọ́ fúnra rẹ̀ ní kété tí o bá tẹ̀síwájú – kò pọndandan láti tẹ̀ 'Fi kún un'. Tẹ̀ ☆ lẹ́gbẹ̀ẹ́ ohun mímu kan láti fi pamọ́ bí ohun mímu déédéé – àwọn ohun mímu déédéé ń hàn bí bọ́tìnnì ní òkè káàdì Ohun mímu, títẹ̀ ẹ̀ẹ̀kan sì ń fi wọ́n kún ọjọ́ náà. ⭐ ń fi oúnjẹ kan pamọ́ bí oúnjẹ tí a fipamọ́. 'Tábìlì ojoojúmọ́' ń fi ohun tí o jẹ hàn pẹ̀lú kálórì àti protein. 💎 kékeré lẹ́gbẹ̀ẹ́ ipò àfojúsùn ní òkè ojú-ìwé ilé ń ṣí i tààrà. Iye kálórì àti protein jẹ́ àfojúdiwọ̀n AI, wọ́n sì lè ní àṣìṣe. O kò jẹ ẹ́ tán? Lábẹ́ oúnjẹ tí a ti sàmì sí, “Mi ò jẹ ẹ́ tán?” ń yọ ìdá kan nínú mẹ́rin, ààbọ̀ tàbí ìdá mẹ́ta nínú mẹ́rin ìpín náà kúrò – tàbí ohun tí o kọ, pẹ̀lú ìṣirò – a ó sì ṣe àtúnṣe kálórì ọjọ́ náà.",
    faq_q_new_me_tracking: "Báwo ni ✓, pípààrọ̀ àti kálórì ṣe ń ṣiṣẹ́ nínú New Me?",
    faq_a_new_me_what: "New Me jẹ́ ètò àkójọ oúnjẹ ojoojúmọ́ tó dá dúró, pẹ̀lú ètò méjì tó ti ṣetán – kálórì 1,300 tàbí 1,500 – tí ó ní oúnjẹ ńlá 2 àti ìpanu 2, pẹ̀lú àṣàyàn 3 fún ọ̀kọ̀ọ̀kan. Ó ní gbogbo Premium nínú. Iye owó: $11.99 lóṣooṣù (fagilé nígbàkígbà) tàbí $99.99 lẹ́ẹ̀kan, fún gbogbo ayé. Ṣí i láti 💎 New Me nínú àkójọ. Kí o tó bẹ̀rẹ̀, ìbéèrè kúkúrú kan wà tí ó bẹ̀rẹ̀ pẹ̀lú ìkìlọ̀ ìṣègùn tí a gbọ́dọ̀ gbà. Ètò náà jẹ́ ìmọ̀ gbogbogbò nìkan, kò sì rọ́pò dókítà tàbí onímọ̀ oúnjẹ ìṣègùn.",
